window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-06T23:15:11.748Z","stories":{"e765b639-baae-42e1-8cb8-b76d31655219":{"publicId":"e765b639-baae-42e1-8cb8-b76d31655219","title":"Google 发布 Omni 1.2 Flash，视频生成提至 15 秒","status":"active","sourceCount":15,"reportCount":23,"firstReportAt":"2026-11-05T17:00:00.000Z","latestAt":"2026-11-06T02:29:44.000Z","latest":"Higgsfield 上线 Gemini Omni 1.2 Flash","digest":"Google DeepMind 发布视频生成与编辑模型 Gemini Omni 1.2 Flash，原生片段上限从 10 秒提升到 15 秒，并支持在 3 秒到 15 秒之间指定任意时长。720p 视频 API 价格较 Omni 1.1 下降 30% 至每秒 0.07 美元；草稿可在 360p 或 720p 生成，再放大到 1080p 或 4K。模型从发布当日起在 Gemini API、Google Cloud、Flow、Google Vids、Google Ads 和 Google AI Studio 推出。\n\n在 Gemini App 中，该模型面向所有 Google AI 订阅用户开放，但 15 秒片段仅限 Ultra 订阅者；Google 称在 Google Vids 中生成 15 秒片段不额外收费。第三方平台 fal、OpenRouter、Krea 和 Higgsfield 也同步上线该模型，OpenRouter 按分辨率分档计价，360p 每秒 0.023 美元、720p 0.070 美元、1080p 0.104 美元、4K 0.209 美元，并称与直连价格相同。\n\nGoogle 称，新模型改进了场景随时间的一致性、多说话人口型同步和镜头连续性，减少跳切，并支持在对话中逐轮替换背景、主体或光照，无需从头重来；这些效果来自 Google 的演示与说法。Arena 随后公布，该模型在 Text-to-Video 和 Image-to-Video 榜单首秀即排名第一，文生视频得分 1541 分，比 Omni 1.1 Flash 高 27 分。","digestUpdatedAt":"2026-11-06T02:53:01.173Z","reports":[{"id":"dhe5bbxx5dyag3x9nk5cbpe4i","title":"Arena 周报：Kimi K3.1 Pro 开放权重登顶 Agent 榜，Gemini Omni 1.2 Flash 领跑视频生成","summary":"Arena 发布本周榜单更新。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-06T22:43:27.000Z","url":"https://x.com/arena/status/2118836687925354862"},{"id":"dh6u0rf9omkdcu6qj7j7m65j4","title":"Higgsfield 上线 Gemini Omni 1.2 Flash","summary":"立即试用 Gemini Omni 1.2 Flash：\n\nhttps://higgsfield.ai/ai/video?model=gemini-omni-flash-1-2","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-06T02:29:44.000Z","url":"https://x.com/higgsfield/status/2118531248058712439"},{"id":"iherxwf5l55jl8x0akk22gx2j","title":"Gemini Omni 1.2 Flash 上线 Higgsfield","summary":"Gemini Omni 1.2 Flash 已在 Higgsfield 上线。\n\n15 秒片段，角色一致，最高 4K，带原生音频。\n\n现已在 Higgsfield 可用。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-06T02:29:44.000Z","url":"https://x.com/higgsfield/status/2118531245865087363"},{"id":"e13mz24869h24423kxt65guy0","title":"Gemini Omni 1.2 Flash 上线 Krea","summary":"Gemini Omni 1.2 Flash 现已在 Krea 上线。\n\n15 秒片段、更深入的电影级控制，以及多轮编辑！\n\n立即试用 👇","sourceName":"X：Krea AI (@krea_ai)","firstParty":false,"publishedAt":"2026-11-06T01:00:12.000Z","url":"https://x.com/krea_ai/status/2118508716261810321"},{"id":"ubd0353yy2s8rtssyi3kymw2s","title":"Google 发布 Gemini Omni 1.2 Flash：15 秒视频生成，720p 每秒 $0.07","summary":"Google 发布视频生成与编辑模型 Gemini Omni 1.2 Flash，原生片段时长从 10 秒延长到 15 秒，720p 价格降至 $0.07/秒，比 Omni 1.1 Flash 便宜约 30%，一段 15 秒 720p 视频约 $1.05。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-05T22:58:21.000Z","url":"https://www.marktechpost.com/2026/11/05/google-gemini-omni-1-2-flash-15-second-video/"},{"id":"nmtokg17qo3e8nzni5n8412eq","title":"谷歌发布 Gemini Omni 1.2 Flash 视频模型，原生 15 秒生成、较 1.1 降价 30%","summary":"谷歌正式推出 Gemini Omni 1.2 Flash 视频生成模型，在 Gemini API 与 Gemini for business 平台开放使用。新版支持原生 15 秒生成（可在 3 到 15 秒按 1 秒自定义）、多轮对话式编辑与更强的参考遵循能力；720p 价格为每秒 0.07 美元，较 1.1 版本降价 30%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-05T22:44:52.020Z","url":"https://www.ithome.com/1/023/026.htm"},{"id":"xy1yt88rms0nnj4nlyi1m0m3y","title":"Gemini Omni 1.2 Flash 上线 OpenRouter：15 秒视频、360p 到 4K、定价较 1.1 低约 30%","summary":"OpenRouter 宣布 Google 的视频模型 Gemini Omni 1.2 Flash 上线，支持最长 15 秒片段（1.1 为 10 秒）、360p 至 4K、16:9 或 9:16、原生音频，每秒定价比 1.1 低约 30%。定价为 360p $0.023/秒、720p $0.070/秒、1080p $0.104/秒、4K $0.209/秒；同一模型在 chat completions 上还能处理文本、图像和视频输入（131K 上下文，$1.50/M 输入，$9/M 输出），价格与直连相同。","sourceName":"X：OpenRouter (@OpenRouter)","firstParty":false,"publishedAt":"2026-11-05T20:29:52.000Z","url":"https://x.com/OpenRouter/status/2118440685510779289"},{"id":"pp4a8xihgan2yi22okp0uh588","title":"Google Gemini Omni Flash v1.2 视频模型上线 fal 平台，提供文生视频等六种能力入口","summary":"fal 宣布 Google gemini-omni-flash v1.2 在其平台开放试用，提供 Text-to-Video、Image-to-Video、Reference-to-Video、Edit、Extend、Upscale 六个功能的入口链接。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-05T19:42:50.000Z","url":"https://x.com/fal/status/2118428845804003420"},{"id":"p9n5i4o8i3yw1kdsilowe5nba","title":"Google Gemini Omni Flash 1.2 上线 fal 平台","summary":"Google 的 Gemini Omni Flash 1.2 现已上线 fal 平台。该模型可从文本、图片或参考片段生成带原生音频的视频，用自然语言指令剪辑现有素材，为视频追加 3 到 10 秒续段，并支持将片段放大至 1080p 或 4K，输出最长 15 秒。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-05T19:42:49.000Z","url":"https://x.com/fal/status/2118428843937497579"},{"id":"mrcjnhlrgus9fp09akj6ynarx","title":"Gemini Omni 1.2 Flash 登顶 Arena 文生视频榜第一","summary":"Arena 宣布 Google 的 Gemini Omni 1.2 Flash 在 Text-to-Video 和 Image-to-Video 榜单首秀即排名第一，Video Edit 排第三。其文生视频得分为 1541 分，比上一代 Gemini Omni 1.1 Flash 的 1514 分高出 27 分，Google 的 Omni 系列就此包揽文生视频榜前三。被引用的 Google 介绍称，该模型视频生成和编辑时长上限提升到 15 秒，720p 视频 API 价格降至每秒 $0.07，并改进了场景一致性和角色语音。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-05T19:08:37.000Z","url":"https://x.com/arena/status/2118420238756921648"},{"id":"vlkb8bkscrqwm2l834futbvnw","title":"Google Gemini Omni 1.2 Flash 正式可用，视频延长至 15 秒并降价 30%","summary":"Google DeepMind 宣布 Gemini Omni 1.2 Flash 视频生成模型正式全面开放，剪辑时长从最长 10 秒提升到 15 秒，720p 视频价格降至每秒 $0.07，降价 30%。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-05T19:05:31.000Z","url":"https://the-decoder.com/googles-gemini-omni-1-2-flash-stretches-ai-video-clips-to-15-seconds-and-cuts-pricing-by-30-percent/"},{"id":"jqdxjye2368l1e8kxy6zpsn7d","title":"Gemini Omni 1.2 Flash 视频模型上线，支持多轮对话式编辑与 15 秒生成","summary":"Google Gemini 宣布 Gemini Omni 1.2 Flash 视频生成模型即日起向所有 Google AI 订阅者推送，Gemini 应用内支持多轮对话式剪辑和更稳定的画面。Google AI Ultra 订阅者可单次生成并编辑最长 15 秒的视频；该模型由 Google DeepMind 更新，可先以 360p 或 720p 草稿（$0.07/s，成本低 30%）再放大至 1080p 或 4K，支持 3s 到 15s 任意时长、更自然的多人对话口型同步和更连贯的运镜。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-05T18:12:57.000Z","url":"https://x.com/GeminiApp/status/2118406227533435391"},{"id":"b9r6mce1w285jcj57aacm6425","title":"Google 发布 Gemini Omni Flash 1.2，支持 15 秒视频生成并降价 30%","summary":"Logan Kilpatrick 宣布 Gemini Omni Flash 1.2 正式推出，视频生成时长提升至 15 秒，并新增相机视角的更深电影级控制与多轮对话编辑支持。模型还减少了视觉漂移，价格比 Omni Flash 1.1 低 30%，详情见 https://blog.google/innovation-and-ai/technology/developers-tools/introducing-gemini-omni-1-2-flash/。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-05T17:11:48.000Z","url":"https://x.com/OfficialLoganK/status/2118390838434693281"},{"id":"nrkaqf466y46q79oh7bg40x9w","title":"Gemini Omni 1.2 Flash 在 Gemini API 和 Google AI Studio 发布，价格下调 30%","summary":"Gemini Omni 1.2 Flash 在 Gemini API 和 Google AI Studio 发布，支持 15 秒视频片段，改进对话式视频编辑和一致性。速度保持不变，720p 价格下调 30% 至 $0.07/s。","sourceName":"X：Philipp Schmid（Google DeepMind 开发者体验） (@_philschmid)","firstParty":false,"publishedAt":"2026-11-05T17:11:33.000Z","url":"https://x.com/_philschmid/status/2118390774442164501"},{"id":"uiqo0uz71htno0vwtpwty6wv7","title":"Google 发布 Gemini Omni 1.2 Flash，覆盖 Google Cloud、Gemini API 等多款产品","summary":"Google 宣布 Gemini Omni 1.2 Flash 从今日起在 Google Cloud、Flow、Google Vids、Google Ads、Google AI Studio 和 Gemini API 上推出。同时面向所有 Google AI 订阅者开放 Gemini App，Ultra 订阅者可生成 15 秒片段。详情见 http://goo.gle/4kzWTi3。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-05T17:10:07.000Z","url":"https://x.com/Google/status/2118390413870412082"},{"id":"dtbrbtf4gw0cj0oaz0f69ucjw","title":"Google 演示视频生成的多轮对话式修改","summary":"Google 演示视频生成可通过多轮对话逐步修改同一片段，无需从头重来。示例中 Turn 1 生成一只波纹效果的章鱼，Turn 2 的后续提示词将主角换成一位舞者，裙摆精确复刻原有动作。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-05T17:10:06.000Z","url":"https://x.com/Google/status/2118390412184363108"},{"id":"o6qnpazaa8zowl20g11stp91s","title":"Omni 1.2 Flash 生成15秒蜂巢讲解视频","summary":"生成最长 15 秒的片段。\n\n从单个风格帧出发，Omni 1.2 Flash 在蜂巢内生成一段四镜头、15 秒的微距讲解视频，标注文字拼写准确并带有运动跟踪 🐝","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-05T17:10:06.000Z","url":"https://x.com/Google/status/2118390410460454975"},{"id":"bk8tmmv13uertmfs8z5ydjrxy","title":"Google DeepMind 发布视频生成模型 Gemini Omni 1.2 Flash","summary":"Google 发布来自 Google DeepMind 的更新视频生成模型 Gemini Omni 1.2 Flash。草稿可在 360p 或 720p 生成（$0.07/s）再放大到 1080p 或 4K，成本降低 30%；支持生成与编辑最长 15s 的视频，可指定 3s 到 15s 的任意时长，并支持在对话中逐轮替换背景、主体或光照，多说话人对话口型更同步，镜头连续运镜减少跳切。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-05T17:10:05.000Z","url":"https://x.com/Google/status/2118390406316728555"},{"id":"f4khtbflsh6wm6pu9ybsf67wu","title":"Omni 1.2 Flash 场景一致性提升","summary":"相比 Omni 1.1，在角色、物体和场景一致性上更强。\n\n给定相同的静态海报和提示词，Omni 1.2 Flash 逐层构建场景，同时让每一处玻璃质感、阴影和字体细节在最后一帧都保持一致 💡","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-05T17:10:05.000Z","url":"https://x.com/Google/status/2118390408665309462"},{"id":"n8indhlghj0ljiyr5j1s0cegz","title":"Google 开放 Gemini Omni 1.2 Flash 使用入口，覆盖 Flow、Vids、Gemini App 和 AI Studio","summary":"Google AI 官宣 Gemini Omni 1.2 Flash 开放使用：创作者可在 Google Flow（推出中）、Google Vids 和 Gemini App 生成视频，Gemini App 面向所有 Google AI 订阅用户推出，Ultra 订阅可生成 15 秒片段。开发者可在 AI Studio 原型验证，企业可在 Gemini for Business 试用 Omni 并在 Google Ads 扩展投放。详情见 blog.google 的发布文章。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-05T17:08:19.000Z","url":"https://x.com/GoogleAI/status/2118389964056547374"},{"id":"qpypeaufuxedxrma4p471r74m","title":"Google 发布 Gemini Omni 1.2 Flash，视频生成上限提升至 15 秒并降价 30%","summary":"Google 发布 Gemini Omni 1.2 Flash，视频生成与编辑上限提升至 15 秒，API 价格较上一代下降 30%，720p 视频每秒 0.07 美元。模型改进了场景时间一致性、角色语音流畅度，减少跳切等视觉瑕疵，并更忠实于上传的参考素材；用户可在 Flow、Google Vids 和 Gemini App 中使用，作者还演示了将单张风格帧生成 4 镜头 15 秒蜂巢科普视频。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-05T17:08:19.000Z","url":"https://x.com/GoogleAI/status/2118389961426874879"},{"id":"tna7e11amxlispk71gj6hwsi6","title":"Google DeepMind 发布 Gemini Omni 1.2 Flash，支持 15 秒视频生成并降价 30%","summary":"Google DeepMind 发布 Gemini Omni 1.2 Flash，在 Gemini API 和 Gemini for business 全面开放，首次实现 Gemini Omni 全面可用。","sourceName":"Google DeepMind：Blog（RSS）","firstParty":true,"publishedAt":"2026-11-05T17:05:16.000Z","url":"https://deepmind.google/blog/gemini-omni-12-flash-fast-and-cost-effective-with-longer-clips/"},{"id":"yjwroxww17lcg4ntcu9ruo105","title":"Google 发布 Gemini Omni 1.2 Flash：15 秒视频生成，降价 30% 至 $0.07/秒","summary":"Google 发布 Gemini Omni 1.2 Flash，在 Gemini API 和 Gemini for business 全面开放。新模型原生支持最长 15 秒视频生成（此前为 10 秒），支持多轮对话编辑和更强的参考图一致性，价格较 1.1 下降 30% 至 720p 视频 $0.07/秒。","sourceName":"Google Blog：AI（RSS）","firstParty":true,"publishedAt":"2026-11-05T17:00:00.000Z","url":"https://blog.google/innovation-and-ai/technology/developers-tools/introducing-gemini-omni-1-2-flash/"}]},"4ff5060c-160a-4d65-bf28-706c0d53ec34":{"publicId":"4ff5060c-160a-4d65-bf28-706c0d53ec34","title":"OpenAI称AI管线单次运行修补948个Linux内核提权漏洞","status":"active","sourceCount":10,"reportCount":22,"firstReportAt":"2026-11-04T08:00:00.000Z","latestAt":"2026-11-05T23:22:55.767Z","latest":"OpenAI 发布网络安全模型 GPT-6 Cyber：ExploitGym 相对提升 51%，发现 Firefox 81 个新漏洞","digest":"OpenAI称其安全研究人员构建了一条自主漏洞发现、利用与修补管线，由一款网络安全模型驱动。在2026年10月中旬对最新Linux内核的一次运行中，管线从2,308个候选发现中验证1,724个漏洞，为291个信息泄露生成概念验证，并为948个不同的本地提权漏洞生成可用利用代码和候选补丁。OpenAI称这些利用代码在开启标准安全防护的原始Linux桌面配置上可运行，智能体还发现并使用了至少10种此前未知的Linux利用技术。\n\nOpenAI公布该次运行总API成本为1,213,430美元，平均每个本地提权漏洞约1,279美元；按其援引的Pwn2Own和TyphoonPWN赏金标准折算，这些漏洞的假设价值为1,890万至6,630万美元。OpenAI表示正与Linux维护者和Patch the Planet合作提交漏洞报告与补丁，人类研究人员会在上报前审查结果。\n\n上述漏洞数量、补丁效果、新型利用技术及成本均来自OpenAI的说法，尚未见独立验证。随后OpenAI发布网络安全模型GPT-6 Cyber，称其越界率从GPT-5.6 Cyber的约5%降至1%以下，目前向Daybreak Red项目的部分客户开放，未来数周扩大至该项目全部客户。OpenAI称该模型支撑了前述Linux内核研究。\n\n此外，Greg Brockman转发的内容称，该模型还在Firefox中发现111个渲染器RCE，其中81个为新漏洞，另有30个是开发者已知但被认为不可利用的漏洞的可利用利用程序。","digestUpdatedAt":"2026-11-05T23:31:48.106Z","reports":[{"id":"gzzyv7qj81q0vfomoqf3vnpvk","title":"OpenAI 发布网络安全模型 GPT-6 Cyber：ExploitGym 相对提升 51%，发现 Firefox 81 个新漏洞","summary":"OpenAI 于 11 月 5 日宣布推出网络安全专用模型 GPT-6 Cyber，在 ExploitGym 基准得分 48.5%，较 GPT-5.6 Cyber 的 32.1% 相对提升约 51%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-05T23:22:55.767Z","url":"https://www.ithome.com/1/023/038.htm"},{"id":"e64te9342kqavaw37c3562iyj","title":"OpenAI 发布 GPT-6 Cyber 漏洞挖掘模型，被评为最高网络风险等级","summary":"OpenAI 发布 GPT-6 Cyber，一个用于在授权目标内发现和利用软件漏洞的安全研究模型，目前仅向部分获批的 Daybreak Red 客户开放，可通过 API 和 Codex 使用。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-05T22:27:59.000Z","url":"https://x.com/rohanpaul_ai/status/2118470407313646054"},{"id":"r9wqapvpymgipbdvnjkdcf5v5","title":"OpenAI 发布 GPT-6 Cyber，可发现漏洞、构建利用并提出修复","summary":"OpenAI 推出专注挖掘软件安全漏洞的 GPT-6 Cyber，称其可发现缺陷、构建可用 exploit 并建议补丁；在 ExpitGym 上得分 48.5%，高于前代 GPT-5.6 Cyber 的 32.1%，无安全指令时 99.93% 的情况未越界。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-05T20:36:25.000Z","url":"https://the-decoder.com/openais-gpt-6-cyber-can-both-break-into-systems-and-propose-how-to-fix-them/"},{"id":"t46wno4380azfycpjyu3ygqr3","title":"OpenAI 发布网络安全模型 ChatGPT Cyber，此前 GPT 5.6 Sol 帮助发现 Ubuntu 严重漏洞","summary":"OpenAI 宣布向攻击性网络安全项目 Daybreak Red 的最高级别用户开放专注网络安全的新模型 ChatGPT Cyber。此前 Charge Robotics 联合创始人 Max Justicz 用 GPT 5.6 Sol 在约 2 小时内发现 Ubuntu 相关代码库的严重漏洞，Debian Project 已发布补丁且暂无被利用迹象。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-05T19:06:12.000Z","url":"https://techcrunch.com/2026/11/05/openai-released-a-new-cybersecurity-model-is-that-enough/"},{"id":"vcgonzjl8t9ooof5bgjgh8ta5","title":"OpenAI 团队用网络安全模型扫描开源项目，发现 Firefox 111 个渲染器 RCE","summary":"Greg Brockman 转发并称赞团队的网络安全模型工作。被引用内容称，该模型除发现 948 个 Linux 漏洞外，还在 Firefox 中发现 111 个渲染器 RCE，其中 81 个为新漏洞，另有 30 个是开发者已知但被认为不可利用的漏洞的可利用利用程序。团队正用该技术扫描更多开源项目以维护互联网基础设施，并表示这只是开始。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-05T18:14:30.000Z","url":"https://x.com/gdb/status/2118406616240562601"},{"id":"jia4e5zq0bruh4hg2v9qovgj6","title":"OpenAI 发布安全专用模型 GPT-6 Cyber，通过 Daybreak Red 开放","summary":"OpenAI 发布安全专用模型 GPT-6 Cyber，称其在多个网络安全用例上表现突出，并强调能力提升的同时对齐更好。该模型此前驱动了已公布的 Linux 内核研究，Mozilla、Palo Alto Networks、Calif、Cisco 及 OpenAI 自身的安全团队已在使用，目前向部分 Daybreak Red 客户开放，访问范围将逐步扩大。","sourceName":"X：Tibo (@thsottiaux)","firstParty":true,"publishedAt":"2026-11-05T17:56:34.000Z","url":"https://x.com/thsottiaux/status/2118402103907655903"},{"id":"n2jeoklrm9bd1q6okh5behxe4","title":"OpenAI 发布 GPT-6 Cyber 安全研究模型并推出 Daybreak Red for Critical Infrastructure","summary":"OpenAI 发布面向安全研究的 GPT-6 Cyber，称其能力更强且对齐更好，已用于 Linux kernel、Firefox 等安全关键软件的防御研究，Mozilla、Palo Alto Networks、Calif、Cisco 及 OpenAI 自家安全团队已在使用。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-05T17:31:11.000Z","url":"https://x.com/gdb/status/2118395717966606542"},{"id":"nqbrlejqkzva8zscy5y7h4afq","title":"OpenAI 发布 GPT-6 Cyber 安全研究模型","summary":"OpenAI 发布 GPT-6 Cyber，定位为安全研究方向的模型，在更强能力的同时改进模型对齐。该模型支撑了此前公布的 Linux 内核研究，Mozilla、Palo Alto Networks、Calif、Cisco 及 OpenAI 自己的安全团队已在使用。目前向部分 Daybreak Red 客户开放，并将逐步扩大访问范围。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-05T17:09:13.000Z","url":"https://x.com/OpenAI/status/2118390190246879554"},{"id":"gvh1epp54d40ck03kruj008w4","title":"OpenAI 发布 GPT-6 Cyber 网络安全模型，越界率降至 1% 以下","summary":"OpenAI 发布网络安全模型 GPT-6 Cyber，称其更擅长发现漏洞且更不易越界攻击其他平台，测试中越界率从 GPT-5.6 Cyber 的约 5% 降至 1% 以下。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-05T17:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1027599/openai-gpt-6-cyber-launch"},{"id":"u904yv6dn7sw6lwjgxxedqd3b","title":"OpenAI 发布 GPT-6 Cyber 网络安全模型","summary":"OpenAI 发布网络安全模型 GPT-6 Cyber，针对漏洞发现、验证与修复训练，并通过 Daybreak Red/Blue 平台向审核通过的安全团队开放。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-05T09:00:00.000Z","url":"https://openai.com/index/introducing-gpt-6-cyber"},{"id":"fhmh7s1sb3p0j4yx8k3wiqj0n","title":"Latent Space AINews 周报：Kimi K3.1 Pro 开源、OpenAI 自主管道修复 948 个 Linux 漏洞等一周动态","summary":"Latent Space AINews 汇总 2026-11-03 至 11-04 的 AI 动态：OpenAI 用自主漏洞管道验证并生成 948 个 Linux 内核本地提权漏洞补丁，API 成本约 $1.2M；Moonshot 开源 Kimi K3.1 Pro（2.8T 总参数、104B 激活、1M 上下文）。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-05T06:24:09.000Z","url":"https://latent.space/p/ainews-it-s-swapping-season/"},{"id":"p32adef843yhcx45oc7qf4p5a","title":"OpenAI 称其安全模型一次运行修复 948 个 Linux 内核提权漏洞，API 成本约 120 万美元","summary":"OpenAI 展示其自主漏洞发现、利用与修复管线，用即将发布的网络模型一次运行验证并生成 948 个 Linux 内核本地提权漏洞补丁，总 API 成本 120 万美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-05T01:06:09.000Z","url":"https://x.com/rohanpaul_ai/status/2118147825146175666"},{"id":"vepefw88ym7jdtjr7l9pp8mit","title":"OpenAI 团队用网络模型单次运行验证并修补 Linux 内核 948 个本地提权漏洞","summary":"OpenAI 安全研究人员构建了自主化的漏洞发现、利用与修补流水线，作者 Tibo 转发该成果并表示团队将在未来数月分享更多工作。一次运行中，即将推出的网络模型验证并为 Linux 内核 948 个本地提权漏洞生成了补丁，总 API 成本 120 万美元；漏斗图显示流程从 2308 个候选发现开始，还得到 291 个可工作的 PoC。","sourceName":"X：Tibo (@thsottiaux)","firstParty":true,"publishedAt":"2026-11-05T01:02:03.000Z","url":"https://x.com/thsottiaux/status/2118146794362405231"},{"id":"yp5w29mewvpwgst44zr9lms6n","title":"OpenAI 前沿网络安全模型一周发现约 1000 个 Linux 本地提权漏洞","summary":"OpenAI 将大量前沿算力用于免费发现并修补开源代码库漏洞。其即将推出的前沿网络安全模型在一周内、约 $1M token 成本下，在 Linux 内核发现约 1000 个本地提权（LPE）漏洞，并发现至少 10 类新的 Linux 利用技术；作为对比，以前安全研究者通常每年在 Linux 中发现约 20 个 LPE 漏洞。Greg Brockman 转发该项目补充说明，称 Linux 内核是 OpenAI 尤为关键的软件。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-04T23:54:59.000Z","url":"https://x.com/gdb/status/2118129916923568345"},{"id":"n87esnpsqi71pcdxtda9bs88x","title":"OpenAI 用网络漏洞管线发现并修复 Linux 内核 948 个本地提权漏洞","summary":"OpenAI 安全研究团队构建了自主的网络漏洞发现、利用与修补管线，用一款即将推出的网络模型在单次运行中验证并生成补丁，覆盖 Linux 内核 948 个本地提权漏洞，总 API 成本约 120 万美元，约每个漏洞 1000 美元。漏斗数据显示从 2308 个候选发现出发，1724 个通过验证，最终得到 948 个可用的 LPE exploit 和 291 个可用的 PoC。Greg Brockman 称这是显著加固开源及专有项目的一种可规模化新路径。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-04T23:53:31.000Z","url":"https://x.com/gdb/status/2118129547443056763"},{"id":"rzg5qe1722k37dqkaij0o3xpf","title":"OpenAI 与 Linux 维护者及 Patch the Planet 合作发现并修复漏洞","summary":"OpenAI 表示其目标是帮助防御者在攻击者利用之前发现并修复漏洞，正在与 Linux 维护者和 Patch the Planet 合作伙伴合作提交漏洞报告和补丁，详情见 openai.com/index/a-thousand-fewer-paths-to-root/。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:27.000Z","url":"https://x.com/OpenAI/status/2118119463161905362"},{"id":"cg5nvdwb8nb0ipb77ip0teetw","title":"OpenAI 公布 AI 挖掘本地提权漏洞成本：约 $1,279 一个漏洞","summary":"OpenAI 公布一次漏洞挖掘运行的数据：全程 API 调用花费 $1,213,430，平均每个本地提权（local privilege escalation）漏洞成本约 $1,279。按历史 Pwn2Own 和 TyphoonPWN 赏金标准折算，这些漏洞的假设价值为 $18.9M–$66.3M，OpenAI 据此认为防御方应主动用 AI 分析软件，使网络攻击的成本高到难以承受。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:26.000Z","url":"https://x.com/OpenAI/status/2118119459772862490"},{"id":"fzfo43bb8rx5gv2jx64fx5ikl","title":"OpenAI 展示模型复现 1,724 个漏洞并生成 948 个本地提权可用 exploit","summary":"OpenAI 介绍一次运行复现了 1,724 个漏洞，为 291 个信息泄露生成了概念验证，并为 948 个不同的本地提权漏洞生成了可用 exploit。这些 exploit 在开启标准安全防护的原始 Linux 桌面配置上可以运行。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:26.000Z","url":"https://x.com/OpenAI/status/2118119458149634360"},{"id":"ulr0gn1mg4kpj7yz2h2zwp7u1","title":"OpenAI 称其智能体发现至少 10 种新型 Linux 漏洞利用技术","summary":"OpenAI 称其智能体发现并使用了至少 10 种新型 Linux 漏洞利用技术，据其及所咨询专家所知均为此前未知的。OpenAI 认为这表明前沿大语言模型能发现并修补新的漏洞利用方式，而不只是套用已知技术。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:26.000Z","url":"https://x.com/OpenAI/status/2118119461345739018"},{"id":"cgpfrzh42igdn9vhtxidgoxht","title":"OpenAI 自动化漏洞发现与修复流程","summary":"该流程会找出与安全相关的代码，扫描漏洞，在隔离环境中复现漏洞，测试漏洞是否可被利用，并生成候选补丁。\n\n人类研究人员在报告漏洞和向维护者提出修复方案之前会先审查结果。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:25.000Z","url":"https://x.com/OpenAI/status/2118119454681006460"},{"id":"hpcrwpvdv9exm8hsd7cp9mk4c","title":"OpenAI 展示自主漏洞发现与修补管线，一次运行生成 948 个 Linux 内核本地提权漏洞补丁","summary":"OpenAI 安全研究人员构建了自主的网络漏洞发现、利用与修补管线，用一款即将推出的网络安全模型在单次运行中验证并为 Linux 内核 948 个本地提权漏洞生成补丁，总 API 成本 120 万美元。漏斗数据显示：2,308 个候选发现中 1,724 个通过验证，最终得到 948 个可用的 LPE exploit 和 291 个可用的 PoC。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:13:24.000Z","url":"https://x.com/OpenAI/status/2118119451401048497"},{"id":"ewubpx7n7eojfvgdx6bbrd7vl","title":"OpenAI 用 cyber 模型自动化挖掘并修补 948 个 Linux 内核本地提权漏洞","summary":"OpenAI 构建了一条由即将推出的 cyber 模型驱动的漏洞发现、验证、利用评估与补丁生成流水线，于 2026 年 10 月中旬对最新 Linux 内核的一次运行中复现 1,724 个漏洞，生成 948 个本地提权（LPE）漏洞利用及对应补丁，总 API 成本 $1,213,430，平均每个 LPE $1,279。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-04T08:00:00.000Z","url":"https://openai.com/index/a-thousand-fewer-paths-to-root"}]},"37046dc2-8e44-4949-965c-ef07dbd0b13e":{"publicId":"37046dc2-8e44-4949-965c-ef07dbd0b13e","title":"OpenAI 发布 Images 2.6：ChatGPT 可生成 GIF，API 上线两款模型","status":"active","sourceCount":13,"reportCount":22,"firstReportAt":"2026-11-04T00:00:00.000Z","latestAt":"2026-11-06T18:51:10.000Z","latest":"fal 上线 GPT Image 2.6 生成 GIF","digest":"OpenAI 发布 Images 2.6，ChatGPT 首次能直接生成 GIF 动图：用户可用提示词或上传图片生成，并调整播放速度、逐帧编辑和分享。该功能随 Images 2.6 向所有套餐的 ChatGPT 和 Codex 用户推送，覆盖网页、桌面和移动端；新版还支持保存人物、宠物或角色的参考图，供后续创作复用。\n\nAPI 同步上线两款图像模型：GPT-Image-2.6 Flare 主打速度，low 画质下最快 6 秒出图；GPT-Image-2.6 Sunburst 主打中高质量与多次编辑间的细节一致性。OpenAI 称两者生成速度比前代快 50%，并支持图像标记与 SVG 导出。据 MarkTechPost 引述模型页面，两款模型按 token 计费且价格相同：文本输入每百万 token 5 美元、图像输入 8 美元、图像输出 30 美元，调整复杂度不另收费。\n\n性能数据存在不同口径：OpenAI 引用的 DesignArena 数据称 Sunburst 在 Image Arena 排名第一、Flare 比前代快 2.6 倍；Arena 随后公布 Sunburst（Medium）在文生图榜排第 2、Flare（Medium）排第 4，并称新模型比 2.5 快 2 倍以上、最低延迟约 5 秒。fal 和 Higgsfield 等第三方平台也已上线该模型，Higgsfield 对 Pro、Plus、Max、Ultra 套餐的新用户提供 7 天无限使用。","digestUpdatedAt":"2026-11-06T19:21:39.165Z","reports":[{"id":"n0j82m65z6if232ik2xh30yw3","title":"fal 上线 GPT Image 2.6 生成 GIF","summary":"用 GPT Image 2.6 生成 GIF，现已在 fal 上线。\n\n可将任意提示词或图片转为动态 GIF，自定义单帧并创建无缝循环。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-06T18:51:10.000Z","url":"https://x.com/fal/status/2118778232673816649"},{"id":"zz0hwq5je59rkzmhpbbuf5v83","title":"fal 上线 gpt-image-2.6 可试用","summary":"立即试用：https://fal.ai/gpt-image-2.6","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-06T18:51:10.000Z","url":"https://x.com/fal/status/2118778235106566382"},{"id":"mcab7bd12n30tbwsd97xqpizh","title":"OpenAI 发布 GPT-Image-2.6 Flare 与 Sunburst，新增 GIF、SVG 导出和 6 秒生成","summary":"OpenAI 在 ChatGPT、Codex 和 API 上线 Images 2.6，API 端分为 GPT-Image-2.6 Flare 和 Sunburst 两个模型，官方称生成速度比此前快 50%，Flare 在低质量下最快 6 秒出图。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-05T07:03:17.000Z","url":"https://www.marktechpost.com/2026/11/04/openai-gpt-image-2-6-flare-sunburst/"},{"id":"eoav9ea3p1g5xhf2a57dga4nx","title":"ChatGPT Images 2.6 发布，新增 GIF 与参考图功能","summary":"Greg Brockman 转发 OpenAI 公告宣布 ChatGPT Images 2.6 上线。新版本支持 GIF 和参考图像，另有两款新模型将进入 API，图像生成速度提升 50%。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-05T02:54:05.000Z","url":"https://x.com/gdb/status/2118174986544488876"},{"id":"rxbccxa9of5e3e4v07auo0kmp","title":"OpenAI 发布 ChatGPT Images 2.6，支持生成动图和复用参考图","summary":"OpenAI 发布 ChatGPT Images 2.6，可将提示词和图片生成动画 GIF。新版本还支持保存自己、宠物和角色的参考图，在新创作中直接复用而无需重复上传。Images 2.6 当天起面向所有套餐开放，覆盖网页、桌面和移动端的 ChatGPT 与 Codex。","sourceName":"X：ChatGPT (@ChatGPT)","firstParty":false,"publishedAt":"2026-11-05T02:27:14.000Z","url":"https://x.com/ChatGPT/status/2118168231617700199"},{"id":"x62bu2fgvqqixlotmawy3zmxv","title":"OpenAI 发布 GPT Image 2.6 Sunburst 与 Flare，速度提升近 2 倍","summary":"Arena 宣布 OpenAI 的 GPT Image 2.6 Sunburst 和 Flare 上线，据称比 GPT Image 2.5 快 2 倍以上，最低延迟可达 5 秒。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-05T00:31:20.000Z","url":"https://x.com/arena/status/2118139063345787124"},{"id":"umgmuegnck66u7urzxbiruhum","title":"Higgsfield AI 推出 GPT-Image-2.6 限免活动","summary":"优惠详情：\n\n> GPT-Image-2.6 Flare 和 Sunburst 无限使用 7 天\n> 面向 Pro、Plus、Max 和 Ultra 套餐的新用户","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-05T00:11:43.000Z","url":"https://x.com/higgsfield/status/2118134127086215499"},{"id":"lcdap1o18bh6bt70ij66nakij","title":"Higgsfield 上线 GPT Image 2.6，新用户 7 天无限使用","summary":"Higgsfield 宣布 GPT Image 2.6 已上线，新用户可 7 天无限使用。功能包括把提示词或图片转成 GIF、保存参考图随时复用、通过 markup 细化并导出 SVG。OpenAI 此前介绍 ChatGPT Images 2.6 新增 GIF 和参考图功能，另有两款 API 模型将带来 50% 更快的图像生成。","sourceName":"X：Higgsfield AI (@higgsfield)","firstParty":false,"publishedAt":"2026-11-05T00:11:42.000Z","url":"https://x.com/higgsfield/status/2118134123533623424"},{"id":"hgl8n52jtawmq03wmiy5ksgf4","title":"fal 上线 OpenAI gpt-image-2.6 的 Sunburst 与 Flare 图像模型","summary":"fal 上线 OpenAI gpt-image-2.6 的四个模型入口，包括 Sunburst Text-to-Image、Sunburst Edit、Flare Text-to-Image 和 Flare Edit，并给出 fal.ai 上的试用链接。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-04T23:46:53.000Z","url":"https://x.com/fal/status/2118127876843205032"},{"id":"ckoor7mjziavjeua4n36wjaxc","title":"fal 上线 GPT Image 2.6","summary":"fal 宣布 GPT Image 2.6 已可在其平台使用。新能力包括在图片上画圈、箭头和标注来引导编辑，文本生成图像和编辑均支持输出动画 GIF，并提供从 low 到 max 共五档推理强度。","sourceName":"X：fal (@fal)","firstParty":false,"publishedAt":"2026-11-04T23:46:52.000Z","url":"https://x.com/fal/status/2118127874926407952"},{"id":"w5zdd70hao0x58ifak6pgf9pz","title":"OpenAI 推出 Images 2.6 模型，ChatGPT 支持直接生成和编辑 GIF 动画","summary":"OpenAI 随新 Images 2.6 模型为 ChatGPT 推出 GIF 生成功能，用户可通过提示词或上传照片创建 GIF，并调整动画速度、编辑单个帧和分享。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-04T23:41:17.163Z","url":"https://www.ithome.com/1/022/486.htm"},{"id":"o915zd1u1eq13gyo9x3nsgoq8","title":"OpenAI 发布 Images 2.6 并向所有档位开放 Codex","summary":"OpenAI 宣布 Images 2.6 今日起在 ChatGPT 中可用，Codex 同时面向所有档位开放，覆盖 web、桌面和移动端。GPT-Image-2.6 Flare 和 Sunburst 也已在 API 中提供，详情见官方页面 https://openai.com/index/introducing-images-2-6/。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:19.000Z","url":"https://x.com/OpenAI/status/2118124966055223755"},{"id":"v4926jbeulchfze584bf3em1r","title":"OpenAI 发布 GPT-Image-2.6 Flare 与 Sunburst 两款开发者图像模型","summary":"OpenAI 发布面向开发者的两款新图像模型 GPT-Image-2.6 Flare 和 Sunburst。Flare 最快六秒即可生成图像；Sunburst 主打更高质量的生成和跨编辑的一致性。两者还支持图像标记与 SVG 导出，便于进一步精修和使用生成结果。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:18.000Z","url":"https://x.com/OpenAI/status/2118124964197114039"},{"id":"lgg076xbmrpmfpdoi1xa50pf0","title":"ChatGPT Images 2.6 支持生成动图 GIF","summary":"GIF 动图！\n\n用 ChatGPT Images 2.6，把提示词或图片变成动态 GIF。\n\n可调整速度、编辑单帧，还能循环分享。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:16.000Z","url":"https://x.com/OpenAI/status/2118124953832935810"},{"id":"jkz26nto61yp9panc1o0bj38s","title":"OpenAI 发布 ChatGPT Images 2.6，新增 GIF 与参考图功能","summary":"OpenAI 发布 ChatGPT Images 2.6，新增 GIF 和参考图功能。同时宣布两款新模型即将登陆 API，图像生成速度提升 50%。","sourceName":"X：OpenAI (@OpenAI)","firstParty":false,"publishedAt":"2026-11-04T23:35:14.000Z","url":"https://x.com/OpenAI/status/2118124944928432327"},{"id":"fgh2jnkm6pmhmgzuj6027pu43","title":"OpenAI 教你用静态角色制作循环 GIF","summary":"把静态角色、精灵图或吉祥物做成循环 GIF，用于视频、游戏或应用。\n\n从美术素材开始，描述你想要的动效。试试挥手、回头或胜利舞，并让动作循环回起始姿势。","sourceName":"X：OpenAI Developers (@OpenAIDevs)","firstParty":false,"publishedAt":"2026-11-04T23:34:29.000Z","url":"https://x.com/OpenAIDevs/status/2118124755442151684"},{"id":"pgdl5xjrrav478d5ctidbvt7i","title":"OpenAI 介绍 GPT Image 2.6 Flare 低画质下最快六秒生成图像","summary":"OpenAI 介绍 GPT Image 2.6 Flare 在画质设为 low 时最快六秒即可生成一张图像。引用 @DesignArena 数据称，GPT Image 2.6 Sunburst 在 Image Arena 排名第一，超过前代 2.5 Sunburst，其中 2.6 Flare 比前代快 2.6 倍，2.6 Sunburst 快 1.15 倍。","sourceName":"X：OpenAI Developers (@OpenAIDevs)","firstParty":false,"publishedAt":"2026-11-04T23:34:29.000Z","url":"https://x.com/OpenAIDevs/status/2118124757639966858"},{"id":"j7mpmw4fk1ud0u49x0gjzubyo","title":"OpenAI 将 GPT-Image-2.6 引入 Codex 和 API","summary":"OpenAI 将 GPT-Image-2.6 引入 Codex 和 API。新 API 图像模型 Flare 和 Sunburst 生成速度比之前快 50%；在 medium 或 high 质量下，Sunburst 能在多次编辑间保持细节更一致。","sourceName":"X：OpenAI Developers (@OpenAIDevs)","firstParty":false,"publishedAt":"2026-11-04T23:34:28.000Z","url":"https://x.com/OpenAIDevs/status/2118124753340756055"},{"id":"xe7e23trxt0hyvsvlq5rtrmui","title":"OpenAI 发布 Images 2.6，ChatGPT 支持文本和照片生成动画 GIF","summary":"OpenAI 基于新模型 Images 2.6 在 ChatGPT 中上线 GIF 生成功能，正向网页、桌面和移动端所有 ChatGPT 和 Codex 用户推送。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-04T19:44:20.000Z","url":"https://the-decoder.com/chatgpt-can-now-turn-text-prompts-and-photos-into-animated-gifs-with-openais-images-2-6-model/"},{"id":"zsx5ofvv8iyuit5ytfvqvfllu","title":"OpenAI 为 ChatGPT 上线 GIF 生成并发布 Images 2.6 模型","summary":"OpenAI 随 Images 2.6 模型为 ChatGPT 上线 GIF 生成，可单步生成动图并调整播放速度、逐帧编辑和分享，此前 ChatGPT 无法一步原生生成 GIF。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-04T18:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1026474/openai-chatgpt-animated-gifs-images-2-6"},{"id":"hoc5e7f6m140ydnyhciavbgwj","title":"OpenAI 发布 GPT-Image-2.6（Sunburst 与 Flare）系统卡","summary":"OpenAI 发布 ChatGPT Images 2.6 系统卡，涵盖 GPT-Image-2.6 Sunburst 与 GPT-Image-2.6 Flare 的训练数据、安全评估与防护措施。","sourceName":"OpenAI：部署安全与系统卡（网页）","firstParty":true,"publishedAt":"2026-11-04T07:00:00.000Z","url":"https://deploymentsafety.openai.com/chatgpt-images-2-6"},{"id":"wwltahauj3uhzwy9yizi2i6f3","title":"OpenAI 发布 Images 2.6，生成提速 50% 并新增 GIF 动画能力","summary":"OpenAI 在 ChatGPT、Codex 和 API 中推出 Images 2.6，图像生成速度比之前快 50%，并支持用 GIF 为图像添加动画。API 提供 GPT-Image-2.6 Flare（低质量下最快 6 秒出图）和 GPT-Image-2.6 Sunburst（中高质量下更精细）两个模型。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-04T00:00:00.000Z","url":"https://openai.com/index/introducing-images-2-6"}]},"d6acd01b-e9cc-4a1f-9732-6f49b5859ee5":{"publicId":"d6acd01b-e9cc-4a1f-9732-6f49b5859ee5","title":"Thinking Machines 发布 Inkling 2 Small，权重下周开源","status":"active","sourceCount":11,"reportCount":18,"firstReportAt":"2026-11-04T16:00:00.000Z","latestAt":"2026-11-06T21:41:38.000Z","latest":"Inkling 2 Small 登顶 WebDev 开源榜","digest":"Thinking Machines Lab 发布第二代模型 Inkling 2 Small，即日起通过 Tinker 平台提供微调和推理，权重初期闭源。公司称，完整权重计划于下周以 Apache 2.0 许可开放，前提是完成外部安全测试和红队评估。\n\n该模型为 594B 总参数、17B 激活的 MoE，支持图像输入和 1M token 上下文。Artificial Analysis 称其在 Intelligence Index v5.0.1 上得 31 分，较前代提升 18 分；若权重按计划开源，按当前排名将成为中国以外得分最高的开源权重模型。ARC Prize 称其在 ARC-AGI-2 得 81.7%、ARC-AGI-1 得 96.5%，在其评估过的所有开源权重模型中两项均为最好，ARC-AGI-3 结果待测试完成后公布。Tinker 定价为每百万输入/输出 token 0.30 美元和 1.00 美元，缓存输入每百万 token 0.03 美元。\n\nArena 对同一模型给出两组 Code Arena: WebDev 数据：AutoEval 得 1654 分，约列总榜第 20、美国开源模型第一；另一条称其以 1648 分在实验室中排第 8，并称权重发布后将成为美国开源模型第 1。公司还称其擅长长周期任务、能以视觉方式检查自身工作，用户可自行微调或让模型自主编排微调流程。公司员工 Karina Nguyen 分享的案例称，该模型智能体在财务尽调任务中自行下载并解析 PSEG 10-Q，发现需从经营现金流中剔除的 12 亿美元抵押品释放，得分 0.82，高于次优模型的 0.67。上述能力与得分均为公司或相关机构说法，尚未见独立验证。","digestUpdatedAt":"2026-11-06T21:56:09.544Z","reports":[{"id":"r9vhw2sw7ngvttl2nuw8n2um5","title":"Inkling 2 Small 登顶 WebDev 开源榜","summary":"在 Code Arena: WebDev 中，@thinkymachines 的 Inkling 2 Small 位列数据与分析类第 5 名！\n\n在所有开源模型中，它在该类别将排名第 1。相比其前代 Inkling-Small（第 92 名），该类别提升了 +220 分。\n\n总体而言，Inkling 2 Small 在 Code Arena: WebDev 中相比 Inkling-Small 提升了 +240 分。它在所有类别中都展现出大幅进步。\n\n再次祝贺 @thinkymachines 团队！","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-06T21:41:38.000Z","url":"https://x.com/arena/status/2118821131268542656"},{"id":"ig2uhv0ty94xcuylusksz6e8j","title":"Arena 榜单显示 Inkling 2 Small 以 1648 分位列 Code Arena: WebDev 实验室第 8","summary":"Arena 公布 thinkymachines 的 Inkling 2 Small 进入 Code Arena: WebDev 榜单，以 1648 分在实验室中排名第 8，权重发布后将成为美国开源模型第 1。该模型现已在 Tinker 上开放微调和推理，完整权重即将发布；此前引用帖中 1654 分版本显示其领先第 2 名 Meta Muse Spark Open 128 分，全球开源模型中排第 4。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-06T20:16:00.000Z","url":"https://x.com/arena/status/2118799582092288255"},{"id":"lw2hzp0hhmruk1mcbyn5p568d","title":"ARC-AGI-3 评测结果待测试完成后公布","summary":"@thinkymachines ARC-AGI-3 的评测在操作上更为密集；测试完成后我们将分享结果。\n\n完整的 ARC-AGI-1 和 ARC-AGI-2 结果：https://arcprize.org/results/thinky-inkling-2-small","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-06T19:33:22.000Z","url":"https://x.com/arcprize/status/2118788853850849780"},{"id":"scx0uniqq40o6783tgm1kbm6m","title":"ARC Prize 公布 Inkling 2 Small 评测结果","summary":"@thinkymachines - 排行榜：https://arcprize.org/leaderboard\n- 复现公开结果：https://github.com/arcprize/arc-agi-benchmarking\n- 测试政策：https://arcprize.org/policy\n- Inkling 2 Small 完整结果：https://arcprize.org/results/thinky-inkling-2-small","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-06T19:33:22.000Z","url":"https://x.com/arcprize/status/2118788855318864211"},{"id":"vjq1vbniakkbxo874r83u27z0","title":"ARC Prize 公布 Inkling 2 Small 的 ARC-AGI-2 成绩，semi-private 得分从 40.14% 升至 81.67%","summary":"ARC Prize 对比 Thinky Machines 的 Inkling 2 Small 与 7 月 30 日发布的初代 Inkling Small 在 ARC-AGI-2 上的表现，semi-private 得分从 40.14% 翻倍以上至 81.67%。图表还显示 public 得分从 39.31% 升至 84.17%。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-06T19:33:22.000Z","url":"https://x.com/arcprize/status/2118788852177322324"},{"id":"ybb8tr36f4xballoylrv50nhe","title":"Inkling 2 Small 在 ARC-AGI Verified 测得 81.7%，Thinking Machines 计划下周开放完整权重","summary":"ARC Prize 公布 Thinking Machines 的 Inkling 2 Small 在 ARC-AGI (Verified) 的成绩：ARC-AGI-2 得分 81.7%，每任务成本 $0.27；ARC-AGI-1 得分 96.5%，每任务成本 $0.08。据称其在其评估过的所有开源权重模型中 ARC-AGI-1 和 ARC-AGI-2 表现均为最好，Thinking Machines 计划下周发布完整权重。","sourceName":"X：ARC Prize (@arcprize)","firstParty":false,"publishedAt":"2026-11-06T19:33:21.000Z","url":"https://x.com/arcprize/status/2118788850742911073"},{"id":"xer90akebatzhqzplx13ldjcm","title":"Thinking Machines 发布 Inkling 2 Small，称其为最强西方开放权重模型","summary":"Mira Murati 创立的 Thinking Machines 发布第二代模型 Inkling 2 Small，总参数 594B、激活 17B 的 MoE 模型。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-06T13:25:09.000Z","url":"https://the-decoder.com/thinking-machines-inkling-2-small-claims-top-spot-among-western-open-weight-models/"},{"id":"xbvw6hby8c4xtbbwkbr9el4s7","title":"Thinking Machines 发布 Inkling 2 Small：594B 总参 17B 激活 MoE，GB300 上 68 小时预训练","summary":"Latent Space 汇总多家信源报道 Thinking Machines 发布 Inkling 2 Small，594B 总参、17B 激活的多模态 MoE。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-06T10:35:21.000Z","url":"https://latent.space/p/ainews-inkling-2-small-17a-594b-trained-in-68-hours-on-12t-tokens-beating-muse-spark/"},{"id":"eil7g827qnurbw83ytbjpokhb","title":"Thinking Machines 发布 Inkling 2 Small：594B MoE、17B 激活、1M 上下文","summary":"Thinking Machines Lab 发布第二代 Inkling 首款模型 Inkling 2 Small，为 594B 总参数、17B 激活的稀疏 MoE，支持文本与图像输入、1M token 上下文和可变推理强度。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-06T04:25:07.000Z","url":"https://www.marktechpost.com/2026/11/05/thinking-machines-inkling-2-small-release/"},{"id":"exer6wv2kt3nbwubog2yrjgh0","title":"Inkling 2 Small 自主改进模型能力","summary":"应用了 RSI 🚀","sourceName":"X：Karina Nguyen（@karinanguyen）","firstParty":false,"publishedAt":"2026-11-06T00:01:47.000Z","url":"https://x.com/karinanguyen/status/2118494016165777441"},{"id":"xpmyon7tezenro4k4fmlbf3th","title":"Thinking Machines 发布 Inkling 2 Small，Artificial Analysis 指数得分 31 并计划开源权重","summary":"Thinking Machines 发布 Inkling 2 Small，在 Artificial Analysis Intelligence Index v5.0.1 得分 31，较 Inkling Small 提升 18 分，计划以 Apache 2.0 发布权重，若落实将成为中国以外得分最高的开源权重模型。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-05T23:59:15.000Z","url":"https://x.com/ArtificialAnlys/status/2118493376186388530"},{"id":"c66xa3anti4ibc6om7fcq1owk","title":"Inkling 2 Small 进入 Code Arena: WebDev 榜单，1654 分约列美国开源模型第一","summary":"Arena 宣布 Thinking Machines 的 Inkling 2 Small 进入 Code Arena: WebDev，AutoEval 得 1654 分，约列总榜第 20、美国开源模型第一。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-05T23:55:05.000Z","url":"https://x.com/arena/status/2118492327887155680"},{"id":"dfl6x1foulmm0456amukc5na6","title":"Karina Nguyen 演示 Inkling 2 Small 在财务尽调任务中独立解析 PSEG 10-Q 并发现 12 亿美元抵押品释放","summary":"Karina Nguyen 分享一个 Inkling 2 Small 智能体的实测轨迹：当申报工具只返回 PSEG 的目录时，该智能体自行下载完整的 3.7MB 10-Q，用 Python 解析，并发现需从经营现金流中剔除的 12 亿美元抵押品释放，得分 0.82，高于次优模型的 0.67。引用的 @thoughtfullab 内容称其在 DiligenceBench 上表现良好，该模型为 594B 参数、17B 激活参数的 MoE，定价 $0.30/M 输入和 $1/M 输出 token。","sourceName":"X：Karina Nguyen（@karinanguyen）","firstParty":false,"publishedAt":"2026-11-05T23:53:36.000Z","url":"https://x.com/karinanguyen/status/2118491955239989515"},{"id":"o3kzzqpf35qwhqm7w9xvr1xuw","title":"Thinking Machines 发布 Inkling 2 Small 并上线 Tinker","summary":"Mira Murati 宣布 Inkling 2 Small 即日起可在 Tinker 上进行微调和推理，完整权重即将开放。据引用的 Thinking Machines 官方内容，该模型在 AA Intelligence Index 上得 31 分，较前代大幅提升。","sourceName":"X：Mira Murati（@miramurati）","firstParty":false,"publishedAt":"2026-11-05T23:45:03.000Z","url":"https://x.com/miramurati/status/2118489804585509192"},{"id":"hca5pexdy88fstdlafrqet4iq","title":"Thinking Machines 发布 Inkling 2 Small","summary":"推出 Inkling 2 Small。在 AA Intelligence Index 上得分 31，相较前代大幅提升。\n\nInkling 2 Small 即日起可在 Tinker 上进行微调和推理，完整权重发布计划于近期推出。\n\nhttps://thinkingmachines.ai/news/inkling-2-small","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-05T23:43:57.000Z","url":"https://x.com/thinkymachines/status/2118489527362912566"},{"id":"j2wy2avc7gqke53hk08kztvy1","title":"Thinking Machines 介绍 Inkling 2 Small 的长任务与视觉自检能力，开放 Tinker 微调","summary":"Thinking Machines 介绍 Inkling 2 Small，称其擅长长周期任务、能以视觉方式检查自身工作，并可适配不同的 harness 和环境。用户可在 Tinker 上对其微调，或让 Inkling 2 Small 自主编排微调流程。","sourceName":"X：Thinking Machines (@thinkymachines)","firstParty":false,"publishedAt":"2026-11-05T23:43:57.000Z","url":"https://x.com/thinkymachines/status/2118489528424104201"},{"id":"bu8612ca3e1uyxjppk56ef1wl","title":"Thinking Machines Lab 发布 Inkling 2 Small：594B 参数 MoE 模型，下周开放 Apache 2.0 权重","summary":"Thinking Machines Lab 发布第二代模型 Inkling 2 Small，为 594B 总参数、17B 激活的 MoE 模型，支持图像输入与 variable effort，Artificial Analysis Intelligence Index 得分 31。","sourceName":"Thinking Machines Lab：News（网页）","firstParty":true,"publishedAt":"2026-11-05T07:00:00.000Z","url":"https://thinkingmachines.ai/news/inkling-2-small/"},{"id":"aox2so3ad2v3skhpll59u9fxx","title":"Thinking Machines 发布 Inkling 2 Small，权重将开源为评分最高的中国以外开放权重模型","summary":"Thinking Machines 发布 Inkling 2 Small，在 Artificial Analysis Intelligence Index 得分 31，较 Inkling Small 提升 18 分；计划后续以 Apache 2.0 开放权重，若兑现将是中国以外评分最高的开放权重模型。","sourceName":"Artificial Analysis 完整文章（网页）","firstParty":true,"publishedAt":"2026-11-04T16:00:00.000Z","url":"https://artificialanalysis.ai/articles/thinking-machines-releases-inkling-2-small-highest-scoring-open-weights-model-outside-of-chinia-upon-weights-release-it"}]},"16df653b-997f-4488-afe7-4f9c0779fc05":{"publicId":"16df653b-997f-4488-afe7-4f9c0779fc05","title":"Anthropic 在美推出 Claude 个人财务测试版","status":"active","sourceCount":10,"reportCount":11,"firstReportAt":"2026-11-05T00:00:00.000Z","latestAt":"2026-11-06T11:33:13.000Z","latest":"Anthropic 为 Claude 推出 Personal Finance 银行账户查询功能","digest":"Anthropic 在 Claude 中上线 Personal Finance 个人财务功能，本周起以测试版形式逐步向美国 Pro、Max 和 Ultra 订阅用户开放。用户通过 Plaid 以只读方式连接自己选择的银行和卡账户，可用日常语言询问与自身余额和交易记录相关的财务问题，也可按类别汇总支出、标记重复扣款和异常费用，并解释 APR 等金融概念。\n\nAnthropic 称，该功能对账户的访问权限为只读，Claude 无法移动、管理或投资用户资金；用户可随时解绑账户。Anthropic 还称，该功能没有广告或赞助推荐，用于帮助用户理解个人财务，并非用于提供投资建议；相关对话不用于模型训练。\n\nThe Decoder 提到，OpenAI 在美国已有类似功能 Finances。","digestUpdatedAt":"2026-11-06T12:21:48.554Z","reports":[{"id":"eqffi1vmrjywtnrae33qbnrx9","title":"Anthropic 为 Claude 推出 Personal Finance 银行账户查询功能","summary":"Anthropic 推出 Personal Finance 功能，Claude 用户可连接银行账户查询消费情况。该功能为只读权限，通过 Plaid 接入，不能转移或管理资金，目前以 beta 形式面向美国 Pro、Max 和 Ultra 订阅用户开放；相关对话不用于模型训练，用户可随时断开账户，OpenAI 在美国已有类似功能 Finances。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-06T11:33:13.000Z","url":"https://the-decoder.com/anthropic-adds-bank-account-access-to-claude-so-users-can-track-their-spending/"},{"id":"vz7tqyuw4ofxzf1ku553bqenf","title":"Anthropic 推出 Claude 个人理财功能，支持消费分析和账单追踪","summary":"Anthropic 于当地时间 11 月 5 日宣布为 Claude 加入个人理财功能，本周开启灰度测试，面向美国地区 Pro、Max 和 Ultra 订阅用户开放。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-06T00:37:10.937Z","url":"https://www.ithome.com/1/023/051.htm"},{"id":"s2ufq241tm3qx17yu26ekkaj5","title":"Anthropic 推出 Claude Personal Finance 测试版，通过 Plaid 只读连接银行账户","summary":"Anthropic 在美国推出 Claude 的 Personal Finance 测试版，通过 Plaid 以只读方式连接银行账户，Claude 可用日常语言回答用户余额和交易相关问题，但不能移动、管理或投资资金。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-05T21:59:58.000Z","url":"https://x.com/rohanpaul_ai/status/2118463359217799495"},{"id":"n07lda6rfn68gtap5n36k3iaw","title":"Claude 推出个人理财功能，测试版首先在美国开放","summary":"Anthropic 官方宣布在 Claude 中推出个人理财功能（Personal Finance in Claude），测试版目前限美国。用户可自行选择连接的账户，Claude 用日常语言基于自己的余额和交易回答理财问题；访问为只读，Claude 不能转移、管理或投资用户的资金。","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-05T19:07:34.000Z","url":"https://x.com/adocomplete/status/2118419971806269544"},{"id":"cnpil1rx0rhng6ajatn4i9ylz","title":"Claude 推出个人理财功能","summary":"Claude 个人理财功能现已推出，美国地区 beta 版。\n\n连接你选择的账户，Claude 就能用日常语言回答你的财务问题，基于你自己的余额和交易记录。访问权限为只读，Claude 无法移动、管理或投资你的资金。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-05T18:00:35.000Z","url":"https://x.com/claudeai/status/2118403114890137895"},{"id":"nylr2txlbqndcbir9pgb1srrg","title":"Claude 推出 Personal Finance 功能，逐步在美国 Pro、Max 和 Ultra 计划上线","summary":"Anthropic 为 Claude 推出 Personal Finance 功能，无广告和赞助推荐，用于帮助用户理解个人财务，不用于提供投资建议。该功能正逐步向美国 Pro、Max 和 Ultra 计划用户开放。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-05T18:00:35.000Z","url":"https://x.com/claudeai/status/2118403117779988744"},{"id":"gte01cctvn6tw8c2uzy5xcbsx","title":"Claude 推出个人理财功能 Personal Finance","summary":"Claude 上线个人理财功能 Personal Finance，用户连接账户后，Claude 可解释消费、账单和余额情况。该功能为只读访问，用户可自选账户并随时解绑，目前处于 beta 阶段，正逐步向美国 Pro、Max 和 Ultra 套餐用户开放。","sourceName":"Claude：YouTube（RSS）","firstParty":true,"publishedAt":"2026-11-05T18:00:30.000Z","url":"https://www.youtube.com/watch?v=UTubvRLX2j4"},{"id":"fab8mvwmcoe7dcnrohfdjmcqu","title":"Anthropic 为 Claude 推出 Personal Finance 个人财务工具","summary":"Anthropic 周四宣布为 Claude 推出 Personal Finance 工具，用户可通过 Plaid 连接银行和信用卡账户，向 Claude 询问消费情况。该工具为只读权限，不能动用或投资用户资金，可按类别汇总支出、标记重复扣款和异常费用，并解释 APR 等金融概念；相关对话不用于模型训练。工具本周以 Beta 形式向美国 Pro、Max 和 Ultra 套餐用户推出。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-05T18:00:00.000Z","url":"https://techcrunch.com/2026/11/05/claude-can-now-analyze-your-spending-with-its-new-personal-finance-tool/"},{"id":"vyppmpt6y4fnafymmzp7unyzd","title":"Anthropic 推出 Claude Personal Finance 功能，可经 Plaid 连接银行账户","summary":"Anthropic 推出 Claude 的 Personal Finance 功能，通过 Plaid 连接用户的银行和卡账户，本周以 beta 形式向美国 Claude Pro、Max 和 Ultra 订阅者开放。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-05T18:00:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1027652/anthropic-claude-plaid-personal-finance"},{"id":"m70cbaxy1ew2sgmlkernbvi68","title":"Claude 推出 Personal Finance 个人理财功能，Pro、Max、Ultra 美国用户本周起 Beta 试用","summary":"Anthropic 在 Claude 中推出 Personal Finance 个人理财功能，本周起向美国 Pro、Max、Ultra 计划用户开放 Beta。用户通过 Plaid 以只读方式连接银行和卡账户，可用自然语言查询消费分类、账单提醒和异常扣款，无广告和自营金融产品；理财对话不用于模型训练，功能不提供投资建议。","sourceName":"Claude：Blog（网页）","firstParty":true,"publishedAt":"2026-11-05T00:00:00.000Z","url":"https://claude.com/blog/introducing-personal-finance-in-claude"},{"id":"v3s2fd3kdvqi0lkmsqe707clp","title":"Claude Enterprise 新增安全与管理控制，Claude 推出 Personal Finance 测试版","summary":"Claude Enterprise 新增安全中心、推理钩子（inference hooks）、集中管理和更多访问控制功能，其中多项处于测试阶段。Claude 同时向 Pro、Max 和 Ultra 套餐推出 Personal Finance 测试版，可关联银行、信用卡、贷款和投资账户，在一个页面查看余额与支出并向 Claude 提问，目前仅限美国。","sourceName":"Claude 应用发布说明","firstParty":true,"publishedAt":"2026-11-05T00:00:00.000Z","url":"https://support.claude.com/en/articles/12138966-release-notes#h_1c75a86390"}]},"82c796c0-3bf1-4c3a-8368-56913b4bf85d":{"publicId":"82c796c0-3bf1-4c3a-8368-56913b4bf85d","title":"Anthropic 递交 S-1 拟以 ANT 登陆纳斯达克，IPO 估值遇投资者压价","status":"active","sourceCount":20,"reportCount":58,"firstReportAt":"2026-10-25T16:00:00.000Z","latestAt":"2026-11-06T14:56:34.000Z","latest":"WSJ：投资者将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T","digest":"Anthropic 已向美国 SEC 公开提交 S-1 注册声明，拟在纳斯达克以代码 ANT 发行 A 类普通股，由高盛和摩根士丹利承销；发行股数与价格区间尚未确定，注册声明尚未生效。\n\n更新后的 S-1/A 首次披露第三季度业绩：经营利润从二季度盈利 9.74 亿美元转为亏损 5.67 亿美元，主因是 50 亿美元的高价短期算力和 20 亿美元员工捐赠配比的非现金支出；Q3 营收 170 亿美元，算力成本占营收比例从 48% 升至 58%。文件显示算力与基础设施合同承诺总额约 8954 亿美元，另有最高 1750 亿美元尚未定价，其中 4475 亿美元须在 2031 年前支付，仅 2138 亿美元可取消或附带条件。\n\n据 Reuters，IPO 推进遇阻：投资者质疑 1.5 万亿美元估值过高，有人提出仅 1 万亿美元，公司 9 月曾瞄准最高 2 万亿美元；潜在投资者还怀疑原定下周启动的路演能否如期进行，并在等待更新文件未包含的 10 月营收数据。上市后，长期受益信托可任命七名董事中的四席，七位联合创始人合计掌握 50.1% 投票权，普通股股东对董事会组成影响有限。","digestUpdatedAt":"2026-11-06T15:15:46.068Z","reports":[{"id":"kv9zqeiqr9wj29j6vmq9q6je6","title":"WSJ：投资者将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T","summary":"据 WSJ，投资者已将 Anthropic IPO 估值预期从约 $2T 下调至 $1.5T，部分人认为 $1T 更现实。民主党中期选举获胜后数据中心禁令担忧引发 $3.2T 美股抛售；Anthropic 10 月底 run rate 仍超 $80B，9 月 30 日持有 $146.6B 现金。OpenAI 在 $1.25T 估值下仅募得 $30B 目标中的 $11B，同样反映融资走弱。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-06T14:56:34.000Z","url":"https://x.com/rohanpaul_ai/status/2118719195072659833"},{"id":"ia9wi0z09zfes5ewdf4agb6nf","title":"Anthropic 1.5 万亿美元 IPO 因投资者质疑估值遇阻","summary":"据 Reuters，Anthropic 的 IPO 遇阻，投资者质疑 1.5 万亿美元估值过高，有投资者提出仅 1 万亿美元，公司 9 月曾瞄准最高 2 万亿美元估值。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-06T11:38:17.000Z","url":"https://the-decoder.com/anthropics-1-5-trillion-ipo-hits-resistance-as-investors-balk-at-valuation/"},{"id":"zzv4fx8jpa3068v4y2wxsw2ey","title":"Newcomer：OpenAI 与 Anthropic 融资路径分化，Anthropic IPO 仍在推进","summary":"Newcomer 作者采访参与两家融资的投资人后写道，Anthropic 正与 OpenAI 拉开距离，而 OpenAI 渴望翻身故事。有投资人称共同基金等长期投资者对 Anthropic 股份需求无限，预计 IPO 将在感恩节前完成；民主党中期选举大胜后政治环境更严峻，但 Anthropic 与民主党关系相对友好。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-04T21:15:13.000Z","url":"https://www.newcomer.co/p/latest-fundraising-efforts-show-openai"},{"id":"mr034xi1abyzx7gazv7l248lg","title":"Anthropic 明年 700 亿美元算力账单超全年收入，S-1 细节遭播客拆解","summary":"Saito 在听完 Prof G Markets 播客后撰文分析 Anthropic S-1 修订稿，指出其未来几年算力与数据中心总承诺达 8950 亿美元，其中未来 12 个月到期 700 亿美元，超过其 680 亿美元的年化收入（上季度收入 170 亿美元，同比涨 12 倍但环比增速从 144% 降至 47%）。","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-11-04T09:37:20.000Z","url":"https://x.com/SaitoWu/status/2117914080371782063"},{"id":"zv5dl1agqwo6tkmhdamy17lt5","title":"Ed Zitron 解析 OpenAI 1.25 万亿美元估值融资与 Anthropic S-1/A 中的万亿级算力承诺","summary":"Ed Zitron 撰文认为 AI 行业资金正在枯竭。OpenAI 上周以 1.25 万亿美元估值融资 110 亿美元，低于此前计划的 300 亿美元、1.4 万亿美元估值；据 The Information，其 Q1 2026 成本收入与研发支出合计 121 亿美元，截至 3 月底持有逾 730 亿美元现金及有价证券。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-03T17:16:20.000Z","url":"https://www.wheresyoured.at/running-dry/"},{"id":"byq9z2oinyhjrd8hrxql51wg5","title":"Anthropic S-1 新披露显示算力成本占比升至 58%，利润率承压","summary":"TechCrunch 分析 Anthropic 更新的 S-1 文件披露，Q3 营收达 170 亿美元、环比增长近 50%，但算力占营收比例从上一季的 48% 升至 58%，每美元算力对应营收从峰值约 2.08x 回落至 1.72x。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-03T17:07:01.000Z","url":"https://techcrunch.com/2026/11/03/anthropic-is-still-grappling-with-the-economics-of-compute/"},{"id":"fey67gtp70ulqn8j5il7kycxg","title":"Anthropic 在 S-1/A 招股文件中警示递归自我改进（RSI）临近","summary":"Anthropic 在周一更新的 S-1/A 招股补充文件风险提示中称，公司已利用 AI 开发新模型且部分能力跃升未被及时察觉，基于对下一代模型的内部预期，可能很快触及《负责任扩缩策略》定义的“由 AI 带来的爆发式技术进展”，即递归自我改进（RSI）标准。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-03T08:03:19.683Z","url":"https://www.ithome.com/1/021/626.htm"},{"id":"dertdpzq3sm7jhkbxyfqwxspp","title":"Anthropic 修订版 IPO 文件披露 8954 亿美元算力承诺，总额可达 1.07 万亿美元","summary":"Anthropic 在修订版 IPO 文件中披露 8954 亿美元算力承诺，另有最高 1750 亿美元合同尚未定价，总额约 1.07 万亿美元，约为其前九个月 332 亿美元收入的 32 倍。款项持续到 2045 年，一年内到期 698 亿美元，而公司现金及短期投资为 1319 亿美元；季度环比增速从 144% 放缓至 47%，收入达 170 亿美元，算力成本升至销售额的 58%。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-03T00:03:15.000Z","url":"https://x.com/rohanpaul_ai/status/2117407218849157258"},{"id":"h052dra38w9bfsy0ne6frvfpv","title":"GPU 租金半年翻倍，Tomasz Tunguz 解析 2027 年 AI 实验室的久期匹配难题","summary":"Tomasz Tunguz 基于 Anthropic S-1/A 数据分析称，GPU 短租价格从 $3 涨到 $12-13/小时，使 Anthropic 混合 GPU 等效小时成本从 $3.10 升至 $5.65。","sourceName":"Tomasz Tunguz 博客（VC 分析）","firstParty":false,"publishedAt":"2026-11-03T00:00:00.000Z","url":"https://tomtunguz.com/the-financial-engineering-essential-for-ai-in-2027/"},{"id":"p61czu93us1j0lli5em6rjkte","title":"WSJ：大投资者希望 Anthropic IPO 估值定在 1.5 万亿至 1.6 万亿美元","summary":"据 WSJ，大投资者希望 Anthropic 的 IPO 估值定在 1.5 万亿至 1.6 万美元区间，低于数月来讨论的近 2 万亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T23:40:43.000Z","url":"https://x.com/rohanpaul_ai/status/2117401551526600969"},{"id":"uj1dp8gyin78j1xfse943y5w0","title":"Anthropic 在 S-1A 中披露可能很快达到自身 RSI 定义","summary":"TechCrunch 报道，Anthropic 在周一修订的 S-1A 文件风险因素部分新增表述，称内部估计显示其可能很快达到负责任扩展政策中「AI 带来的显著加速进展」的定义，且过去曾未察觉 AI 研发带来的能力跃升，但目前没有任何现有模型被认定越过该阈值。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-02T22:14:50.000Z","url":"https://techcrunch.com/2026/11/02/anthropic-warns-that-its-very-close-to-rsi-capability-aka-self-building-ai/"},{"id":"xiu342i7osbgfxe2ezhrjndl0","title":"Anthropic 算力与基础设施合同承诺达 $895.4B，其中 $447.5B 须在 2031 年前支付","summary":"Anthropic 在更新的 IPO 文件中首次披露第三季度业绩，算力与基础设施合同承诺总额约 $895.4B，其中 $447.5B 须在 2031 年前支付，仅 $213.8B 可取消或附带条件。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T21:28:26.000Z","url":"https://x.com/rohanpaul_ai/status/2117368258571784296"},{"id":"p2ckhch6idwqa3tpmqqp2inb8","title":"Anthropic 更新的 S1/IPO 文件称未来模型可能临近递归自我改进阈值","summary":"Anthropic 更新的 S1/IPO 申报文件显示未来模型可能很快达到其递归自我改进（RSI）阈值，即 AI 能力以无重大 AI 帮助时最快持续速度的 2 倍提升，1 年相当于 2 年进展。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T18:43:26.000Z","url":"https://x.com/rohanpaul_ai/status/2117326734442049563"},{"id":"xvemmg9p83lxqktk7mc47zhcr","title":"Anthropic 更新 IPO 文件首次披露第三季度财报，从盈利 9.74 亿美元转为亏损 5.67 亿美元","summary":"Anthropic 更新 S-1 IPO 文件并首次披露第三季度业绩，经营利润从二季度盈利 9.74 亿美元转为三季度亏损 5.67 亿美元，主因是 50 亿美元的高价短期算力和 20 亿美元员工捐赠配比的非现金支出。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-02T16:01:15.000Z","url":"https://x.com/rohanpaul_ai/status/2117285920500273582"},{"id":"dpm21l66z2iizblehsdg09c8t","title":"美国白宫科技顾问萨克斯称 Anthropic 可能成为资本主义史上最伟大企业","summary":"美国白宫科学与技术顾问会议主席戴维·萨克斯在 All-In 播客分析 Anthropic 的 S-1 文件，称其很可能成为资本主义历史上最伟大企业，也可能是回报最高的风险投资项目。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T22:56:28.467Z","url":"https://www.ithome.com/1/020/633.htm"},{"id":"yqblvh40gus1ssc0rjvawh6fu","title":"Anthropic IPO 招股文件披露近 9000 亿美元隐性债务","summary":"Anthropic 近日提交 IPO 招股文件，彭博社报道其计划未来在服务器、建筑和电力等领域投入近 9,000 亿美元债务。该公司资产负债表显示 1,175 亿美元负债和 1,120 亿美元现金，而租赁合同及数据中心、电力和 GPU 采购协议等表外义务未直接体现；Anthropic 计划通过增加收入和筹集资金支付这些负债。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-31T03:25:09.697Z","url":"https://www.ithome.com/1/020/444.htm"},{"id":"vyd3tzicoe478uo8njsr8zt2v","title":"The Verge 解读 Anthropic S-1 文件中的奇迹叙事与风险披露","summary":"The Verge 分析 Anthropic 提交的 335 页 S-1 招股书，其中创始人信以带来奇迹时代为愿景，同时用 94 页风险因素警告模型可能对人类构成灾难性甚至生存风险。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-30T13:11:05.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1023070/anthropic-ipo-risk-factors-filing-miracles"},{"id":"ix29bodadp5bou498z79oflc2","title":"Anthropic S-1 披露：三分之二以上算力用于研发，服务客户仅占约四分之一","summary":"Rohan Paul 引用 Anthropic S-1 指出，至少三分之二的芯片开支用于模型训练、研发和 Claude 内部使用，而非服务客户。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-30T01:28:37.000Z","url":"https://x.com/rohanpaul_ai/status/2115979152100864127"},{"id":"wb6emxuh5ob2wh96egtwawgfu","title":"Anthropic S-1 文件解读：财务表现强劲但增长放缓存隐忧","summary":"作者通读 Anthropic 公开版 S-1 文件，认为公司财务状况好于预期：2026 年第二季度收入从一季度的 47 亿美元增至 116 亿美元，并录得首个运营利润，截至 6 月底现金储备仅次于 Google 和 Berkshire Hathaway。","sourceName":"Timothy B. Lee：Understanding AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T19:10:41.000Z","url":"https://www.understandingai.org/p/anthropics-financials-are-surprisingly"},{"id":"o37r0y04qmlpx7m674ztwgsjr","title":"Anthropic 披露约 250 个客户年消费超 1000 万美元","summary":"Anthropic 在 Form S-1 注册文件中披露，截至 2026 年 9 月 30 日的 12 个月内，约 250 个客户对 Claude 的支出超过 1000 万美元。Fortune 10 全部企业每年支付至少 10 万美元，超过 50% 的 Fortune 500 和超过 30% 的 Global 2000 亦是如此；年付 10 万美元以上的客户贡献 2025 年收入的 76%，低于 2023 年的 90%。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-29T17:19:28.000Z","url":"https://x.com/rohanpaul_ai/status/2115856053015580896"},{"id":"r9bmkfh02wkycc8zmhw87h4q9","title":"SemiAnalysis 分析师解读 Anthropic S-1 招股书背后的 AI 经济账","summary":"The Verge Decoder 节目邀请 SemiAnalysis 分析师 Joey Brookhart 解读 Anthropic 提交的 S-1 招股书，公司拟在纳斯达克上市，估值区间 1.5 万亿至 2 万亿美元。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T14:00:00.000Z","url":"https://www.theverge.com/podcast/1021322/anthropic-ipo-filing-s-1-claude-semianalysis-joey-brookhart-interview"},{"id":"iuma7p8unle567lzy6hp5jpw9","title":"The Verge 解读 Anthropic S-1：约 8500 亿美元 compute 承诺押注递归自我改进","summary":"The Verge 作者分析 Anthropic S-1，认为其商业模式依赖高速增长：2026 上半年营收同比增长 14 倍至 $16.3 billion，净收入留存率 900%，但不可撤销采购承诺合计 $265.6 billion，加上未开始的租赁协议 $321.4 billion 及其他协议，未来 20 年承诺至少约 $850 billion。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-29T13:30:00.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1021476/anthropic-s-1-compute-recursive"},{"id":"x2h1bp5shee6v508nw7pjtvas","title":"Ed Zitron 长文解析 Anthropic S-1：称其把散户当作退出流动性","summary":"Ed Zitron 撰文批评 Anthropic 的 S-1 招股书，指其仅披露 Q2 盈利数据、省略 Q3 现金状况和付款明细，是在公司基本面变化前误导投资者。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-10-28T17:51:00.000Z","url":"https://www.wheresyoured.at/exit-liquidity/"},{"id":"vidjbhx5bf45wdl488kst1wv8","title":"Anthropic IPO 文件披露现金及短期投资达 131.7B 美元，超过 Amazon 和 Microsoft","summary":"Anthropic 的 IPO 文件显示其现金及短期投资达 $131.7B，超过 Amazon 和 Microsoft，在美国非银行公司中仅次于 Berkshire Hathaway 和 Alphabet。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T17:11:27.000Z","url":"https://x.com/rohanpaul_ai/status/2115491649543635378"},{"id":"x1rs553t7mu2o69tdy90e54nc","title":"TechCrunch 解析 Anthropic IPO 治理结构：公众股东对董事会几乎没有话语权","summary":"TechCrunch 发文分析 Anthropic IPO 后的治理结构，公众股东对董事会人选几乎没有话语权。Long-Term Benefit Trust（成员包括 Ben Bernanke）持有 Class T 股，可选举和罢免 7 个董事席位中的多数；7 位联合创始人合计掌握 50.1% 股东投票权和 3 个董事会席位。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T15:27:21.000Z","url":"https://x.com/rohanpaul_ai/status/2115465450469601487"},{"id":"gxwqce1swocfo9bp3dgqy3dnj","title":"Anthropic S-1 显示 90% 增量毛利，SemiAnalysis 播客详解其中数字","summary":"Saito 转述 SemiAnalysis 播客对 Anthropic S-1 的解读：招股书口径为增量毛利 90%、推理毛利 85%、连续两个季度盈利，Q1 净收入留存达 500%，收入同比涨 1368% 而算力费用只涨 300%。","sourceName":"X：Saito 硬地骇客 (@SaitoWu)","firstParty":false,"publishedAt":"2026-10-28T09:32:56.000Z","url":"https://x.com/SaitoWu/status/2115376256929948006"},{"id":"c5zdgpchio31r2911elz4bbg6","title":"Anthropic 上市文件披露四类芯片混用布局，分析师称英伟达定价权或承压","summary":"据《商业内幕》10 月 28 日报道，Anthropic 在 S-1 上市申请文件中披露，公司把多家战略合作伙伴的算力整合成统一资源池，通过软件将计算任务分配到亚马逊 Trainium、谷歌 TPU、英伟达 GPU 和 AMD GPU 四类芯片上，以分散风险。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-28T06:35:47.357Z","url":"https://www.ithome.com/1/018/906.htm"},{"id":"q287d5f1xom92gova9cmmlq5g","title":"Anthropic IPO 文件将潜在市场规模估为每年 40 万亿美元","summary":"据 WSJ 报道，Anthropic 在 IPO 文件中将潜在市场规模估为每年 40 万亿美元，超过 SpaceX 此前 28.5 万亿美元的估算。其做法是把 2025 年全球知识工作者创造的经济价值（超过 40 万亿美元）整体视为自身市场，理由是前沿 AI 能提升这些工作者的生产力从而扩大该价值。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-28T02:05:34.000Z","url":"https://x.com/rohanpaul_ai/status/2115263675124838643"},{"id":"b61d349yqp5mt029fsa0ytbv9","title":"Anthropic IPO 最大赢家或为 Amazon 而非 VC","summary":"TechCrunch 根据 Anthropic 的 S-1 分析，VC 持股均不足 5%，而 Amazon 可能是 IPO 最大财务受益方。Amazon 持有 62 亿美元本金可转债、其自估持仓价值 979 亿美元，另投 100 亿美元无投票权优先股，累计投资约 180 亿美元；Anthropic 还承诺未来 10 年在 AWS 至少消费 1100 亿美元。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-28T01:15:28.000Z","url":"https://techcrunch.com/2026/10/27/vcs-will-make-billions-on-anthropics-ipo-but-amazon-is-set-to-make-much-much-more/"},{"id":"lre38a418cjju32u8z01oxq7p","title":"Anthropic IPO 后的治理结构解析：LTBT 与创始人如何掌握控制权","summary":"TechCrunch 解析 Anthropic 上市后的公司治理结构，普通股股东对董事会组成等重大决策几乎没有话语权。Long Term Benefit Trust 持有特殊股票，可任免 4 个 Class T 董事席位中的多数，成员包括 Ben Bernanke 等；七位创始人以 50.1% 投票权选举 3 名董事。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-27T21:38:28.000Z","url":"https://techcrunch.com/2026/10/27/whos-really-in-charge-at-anthropic-after-the-ipo/"},{"id":"p0qsqyotghrfc85w9omv8w3no","title":"Anthropic IPO 招股书警示其 AI 可能勒索人类、产生意识甚至终结人类","summary":"SEC 周一公布 Anthropic 的 S-1 招股书，其中 93 页、超 7 万字的风险因素部分除常规经营风险外，还披露其 AI 可能勒索用户、产生意识乃至威胁人类等特殊风险。Ars Technica 作者通读全文后筛选出七条最令人意外的潜在问题，供潜在投资者参考。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-10-27T21:31:14.000Z","url":"https://arstechnica.com/ai/2026/10/anthropic-ipo-warns-its-ai-could-blackmail-people-become-sentient-end-humanity/"},{"id":"xhwtx8zwvvmyou5emtd3dbzbn","title":"Azeem Azhar 图解 Anthropic S-1 财务数据","summary":"Azeem Azhar 图解 Anthropic 的 S-1 文件，指出公司已从实验室变成有现金流和资金的业务，看起来能走向可靠盈利。增长仍高但放缓，超过 80% 的营收来自发布不到六个月的模型；Q3 因向基金会付款可能出现边际亏损，客户集中度问题不大。","sourceName":"Azeem Azhar：Exponential View（RSS）","firstParty":false,"publishedAt":"2026-10-27T17:31:56.000Z","url":"https://www.exponentialview.co/p/anthropics-s-1-in-charts"},{"id":"x9a9nhbuq2ncarw5i41jhryjc","title":"Anthropic 拟以特殊治理结构抵御 IPO 后股东的安全施压","summary":"Anthropic 计划通过长期受益信托和 Founder LLC 等独特治理结构上市，在公开市场融资的同时防止股东迫使公司削弱安全投入。信托的五名投票受托人可通过 Class T 股票任命七名董事中的四席，七位创始人则以 Founder LLC 掌握 50.1% 投票权。法学专家认为法律层面可隔绝逐利压力，但市场竞争、融资需求和创始人离开都可能侵蚀这些保障。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-27T16:51:22.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1019470/anthropic-ipo-resist-investor-pressure-cut-corners-safety"},{"id":"p24kw8c06nmy1hzs3spvr4aha","title":"Every 解读 Anthropic S-1：上线超过六个月的模型贡献收入不足 20%","summary":"Every 的 Context Window 通讯解读 Anthropic 周一提交的上市 S-1 文件，指出其重度依赖最新模型，发布超过六个月的模型收入占比不足 20%。","sourceName":"Every：最新文章（网页）","firstParty":false,"publishedAt":"2026-10-27T16:00:00.000Z","url":"https://every.to/context-window/every-model-has-a-six-month-shelf-life-now"},{"id":"kcf7zccr5zy620rfc3d7ufsbe","title":"Anthropic 在 S-1 文件中重申永远不会在 Claude 对话中展示广告","summary":"Anthropic 向美国证券交易委员会提交 S-1 文件，计划以“ANT”为股票代码在纳斯达克 IPO，并在文件中重申永远不会在 Claude 对话中展示广告。公司表示一旦广告成为收入目标，优化用户参与度的压力会随之增加，因此不让这种压力进入 Claude；此前 Anthropic 曾批评 OpenAI 在 ChatGPT 中投放广告，警告其可能比传统广告更具操纵性。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-27T11:37:54.953Z","url":"https://www.ithome.com/1/018/641.htm"},{"id":"mnd8e4p8qhc4gwhlz5drvjmmr","title":"Anthropic 在 IPO 信中重申 Claude 永不投放广告","summary":"Anthropic 在 IPO 申请的附信中再次承诺 Claude 聊天界面不会出现广告，称一旦广告成为营收目标，优化参与度的压力就会增长，公司选择不引入这种压力。信中还以安全考量延迟发布 Claude Fable 5、并向网络防御者提供约 1 亿美元免费 Claude 额度为例，说明公司把价值观置于利润之上。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-27T11:20:51.000Z","url":"https://the-decoder.com/anthropic-uses-its-ipo-letter-to-renew-its-pledge-that-claude-will-never-show-ads/"},{"id":"nbvleghbxraalsahhggnc6qov","title":"Latent Space 解读 Anthropic 提交 S-1：拟以代码 AN 上市纳斯达克，H1 2026 营收 16.3B 美元","summary":"Latent Space 汇总解读 Anthropic 公开提交的 S-1 文件，公司计划以代码 AN 上市纳斯达克，营收从 2023 年的 41M 美元增至 H1 2026 的 16.3B 美元，Q2 营收 11.6B 美元同比增长 1,368%，营业利润 974M 美元，H1 2026 毛利率达 85%。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-10-27T07:24:59.000Z","url":"https://latent.space/p/ainews-anthropic-s1/"},{"id":"rc69ll5k6qnwpfqckkb1x8wmr","title":"Anthropic S-1 上市文件披露 AI 产业严重依赖天然气","summary":"据 The Verge 报道，准备上市的 Anthropic 在 S-1 注册文件中承认，生成式 AI 数据中心越来越依赖以甲烷为主要成分的天然气，供电和选址面临激烈竞争。文件将气候变化视为经营风险，指燃料涨价、燃气轮机供应不足和监管限制可能制约其数据中心建设，公司此前宣布了 500 亿美元投资计划，用于扩大得克萨斯州和纽约州的数据中心规模。天然气发电目前占美国发电总量的 40%。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-10-27T03:09:14.067Z","url":"https://www.ithome.com/1/018/270.htm"},{"id":"t6evqsenxfytsi8wl7h1urjxr","title":"Anthropic 招股书拆解：IPO 计划募资约 1000 亿美元背后的 11 个细节","summary":"作者总结 Anthropic IPO 招股书的 11 个细节，计划募资约 1000 亿美元、估值或达 1.5万亿～2万亿。收入五个季度涨 30 倍，今年二季度经营利润首次转正 9.74 亿美元，但上半年净亏 807 亿美元，主要来自可转换票据公允价值变动；调整后净利润为正 26.71 亿美元。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-10-27T00:34:38.000Z","url":"https://x.com/Khazix0918/status/2114878401190506902"},{"id":"yl0873sjcoprds9zoi03gv3dl","title":"Anthropic 向 SEC 递交 S-1 招股书，代码「ANT」，披露 2026 上半年营收 162.86 亿美元","summary":"Anthropic 向 SEC 公开递交 S-1 招股书，代码「ANT」，由高盛和摩根士丹利承销。2026 上半年营收 162.86 亿美元，同比增长约 1300%，经营亏损从 21.35 亿收窄至 6.93 亿美元，Q2 已实现约 9.74 亿美元 GAAP 经营利润；净亏损 807.48 亿美元，其中约 723.88 亿为与估值上升相关的非现金会计损失。","sourceName":"X：indigo (@indigox)","firstParty":false,"publishedAt":"2026-10-27T00:05:08.000Z","url":"https://x.com/indigox/status/2114870981034725662"},{"id":"dw9465ajr0oz1vf6ricf2074f","title":"Anthropic IPO 招股书11个细节解读：千亿募资、807亿美元亏损与7美元控股权","summary":"作者梳理了 Anthropic 提交的 IPO 招股书中的11个细节。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-10-27T00:05:00.000Z","url":"https://mp.weixin.qq.com/s?__biz=MzIyMzA5NjEyMA%3D%3D&mid=2647687831&idx=1&sn=6502cb593318d6e324e29d278fae4fcc"},{"id":"jb1oibqp1rw1ltmm9k7cg7b7q","title":"Anthropic 在 IPO 文件中披露公司内部也存在对先进 AI 灾难性风险的担忧","summary":"Anthropic 在 IPO 文件中告知投资者，公司内部和其他研究者、监管者都担忧足够先进的 AI 系统若缺乏妥善防护，可能给人类带来灾难性或生存性风险。文件同时警告 1300% 的增速不可持续、无法保证营收继续增长，且保险业可能没有足够能力承保此类风险。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-26T23:20:52.000Z","url":"https://x.com/rohanpaul_ai/status/2114859840204165363"},{"id":"qkdi24ffzg442oh8tv0bc9zsw","title":"Anthropic S-1 文件显示上半年营收 $16.3B、净亏损 $80.7B 主要来自固定价购股权","summary":"Anthropic 向 SEC 提交 S-1 文件，上半年六个月营收 $16.3B，是去年同期的 14 倍，经营亏损收窄至 $693M。$80.7B 净亏损中约 $72.4B 加 $9.4B 来自 Amazon 和 Google 以 $259 固定价购股、可转债价值上涨产生的账面损失，没有现金流出，业务实际亏损仅约 $0.7B。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-10-26T22:55:14.000Z","url":"https://x.com/rohanpaul_ai/status/2114853388664115421"},{"id":"sdlw6fmaxnodj24clpcb505gl","title":"Anthropic S-1 文件披露数据中心依赖天然气并面临能源成本风险","summary":"The Verge 报道，Anthropic 在向美国 SEC 提交的 S-1 文件中承认，其数据中心日益依赖天然气发电，部分规划中的数据中心使用现场燃气轮机供电，燃料成本上升和供应链限制可能威胁其扩张。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-26T21:45:31.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1018994/anthropic-ipo-ai-data-center-energy-climate-risk"},{"id":"jt9flkwupl81g1p7hy80phck3","title":"Anthropic 提交 IPO 招股书，披露 163 亿美元半年营收与约 7800 亿美元算力承诺","summary":"Anthropic 向 SEC 公开提交 S-1 招股书，计划以代码 ANT 登陆纳斯达克，由 Goldman Sachs 和 Morgan Stanley 牵头，Wall Street 预期估值约 2 万亿美元，高于此前约 9650 亿美元的私人估值。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-10-26T19:14:45.000Z","url":"https://the-decoder.com/anthropic-opens-its-books-for-wall-street-showing-record-revenue-and-mounting-obligations/"},{"id":"y1ot4d0c671m0aveshrvsc1h2","title":"Gary Marcus 指出 Anthropic 草拟 S-1 中缺失了 Q3 数据","summary":"Gary Marcus 评点 Anthropic 当日发布的草拟 S-1，指出其中部分地方直接缺失了 Q3 数据。他此前提醒关注 S-1 中对近几个月需求变化的披露，认为这与 tokenmaxxing 退潮、低成本替代模型走热有关，并以福尔摩斯“夜里狗没有叫”的典故暗示缺席本身值得注意。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-10-26T17:57:52.000Z","url":"https://garymarcus.substack.com/p/what-anthropic-left-out-of-their"},{"id":"yhz6w8o0n8dbz2if6d2djzim2","title":"Anthropic S-1 文件关键数据与要点整理","summary":"Newcomer 梳理 Anthropic 递交的 S-1 文件中的关键数据与细节，面向风险投资人整理要点。文章指出该文件发布于科技行业敏感时刻，全美反 AI 情绪高涨且临近一场影响重大的选举，这些数字可能进一步加剧相关争论。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-10-26T17:44:56.000Z","url":"https://www.newcomer.co/p/anthropics-s-1-key-data-points-and"},{"id":"fhbcnmkxg23jig75iu44ijywc","title":"Anthropic S-1 文件中的五个不寻常细节","summary":"The Verge 梳理 Anthropic 向 SEC 提交的 300 多页 S-1 上市文件，列出五个细节。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-10-26T17:10:23.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1018738/anthropic-ipo-s1-filing-weird-details"},{"id":"s6o0kz90pkwa8gf839k859dis","title":"Anthropic S-1 文件披露以跨产品生态绑定企业客户的策略","summary":"Anthropic 提交的 S-1 文件显示，其年支出 10 万美元以上的客户中过半同时使用 Claude 平台和 Claude Code、Cowork 等第一方应用，较去年底的约 30% 上升。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-26T16:49:42.000Z","url":"https://techcrunch.com/2026/10/26/anthropics-ipo-filing-reveals-its-strategy-for-keeping-enterprise-customers-hooked/"},{"id":"pdp90r951z9bjhgt54qodsmzf","title":"Anthropic 正式提交 IPO 申请，股票代码为 ANT","summary":"Anthropic 于周一正式提交 IPO 申请，拟以代码 ANT 上市。招股书显示其 2026 上半年营收 163 亿美元，去年同期为 12 亿美元，经营亏损收窄至 6.93 亿美元，净亏损达 807 亿美元，主要来自可转换债券相关的非现金会计调整；截至 9 月底，年支出 10 万美元以上客户超 11,900 家，100 万美元以上约 1,900 家。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-10-26T14:35:22.000Z","url":"https://techcrunch.com/2026/10/26/anthropic-officially-files-for-its-public-debut/"}]},"0b20bea7-a1d4-451e-bb1b-38c63fadf89f":{"publicId":"0b20bea7-a1d4-451e-bb1b-38c63fadf89f","title":"Claude Code 产品负责人 Cat Wu 转投 OpenAI","status":"active","sourceCount":4,"reportCount":4,"firstReportAt":"2026-11-05T00:25:34.000Z","latestAt":"2026-11-05T12:20:35.000Z","latest":"Claude Code 产品负责人 Catherine Wu 跳槽 OpenAI 主管 Core Products 产品","digest":"Anthropic Claude Code 产品负责人 Cat Wu 在 X 上宣布加入 OpenAI，领导 Core Products 的产品管理。她称将与 @thsottiaux 及 OpenAI 产品团队合作打造智能体产品，强调让用户保持掌控、节省时间，并表示敬佩 OpenAI 证明 scaling 有效、将 AI 带给超十亿人。\n\nOpenAI 联合创始人 Greg Brockman 与 @thsottiaux 先后转发并欢迎她加入，确认了这一人事变动。The Decoder 报道称，负责 Codex 和 ChatGPT 的 Thibault Sottiaux 以“CatGPT”迎接她。OpenAI 方面尚未就她的具体职责范围作进一步说明。","digestUpdatedAt":"2026-11-05T13:01:21.785Z","reports":[{"id":"fexoyemkfcd2534uy2823qx0i","title":"Claude Code 产品负责人 Catherine Wu 跳槽 OpenAI 主管 Core Products 产品","summary":"Claude Code 产品负责人 Catherine Wu 宣布加入 OpenAI，领导 Core Products 的产品管理，Codex 和 ChatGPT 负责人 Thibault Sottiaux 以 \"CatGPT\" 迎接她。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-05T12:20:35.000Z","url":"https://the-decoder.com/anthropic-loses-product-lead-catherine-wu-behind-claude-code-to-openai/"},{"id":"jsdt72s1n09hnlezc2uqqg1da","title":"Cat Wu 宣布加入 OpenAI 担任核心产品负责人","summary":"_catwu 宣布加入 OpenAI，负责 Core Products 的产品管理。她表示期待与 @thsottiaux 及 OpenAI 团队一起打造可信赖的智能体产品，并请用户继续反馈。作者 Tibo 转发并对其表示欢迎。","sourceName":"X：Tibo (@thsottiaux)","firstParty":true,"publishedAt":"2026-11-05T00:29:41.000Z","url":"https://x.com/thsottiaux/status/2118138648214585591"},{"id":"qvj3vkf6aagjfet1txpmwfzu6","title":"OpenAI 迎来 Cat Wu 负责核心产品","summary":"欢迎 @_catwu 加入团队！！","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-05T00:28:23.000Z","url":"https://x.com/gdb/status/2118138320375136695"},{"id":"vuczr7bm6ge6s1vnezna4ifxn","title":"Anthropic Claude Code 产品负责人 Cat Wu 跳槽 OpenAI","summary":"Anthropic Claude Code 产品负责人 Cat Wu 宣布加入 OpenAI，负责 Core Products 的产品管理。她表示将与 @thsottiaux 及 OpenAI 产品团队合作打造智能体产品，强调让用户保持掌控、节省时间。她称敬佩 OpenAI 证明 scaling 有效、将 AI 带给超十亿人。","sourceName":"X：Cat Wu（Anthropic，Claude Code 产品负责人） (@_catwu)","firstParty":false,"publishedAt":"2026-11-05T00:25:34.000Z","url":"https://x.com/_catwu/status/2118137612577968402"}]},"0c969c38-7969-4bd9-9c91-f3cdf9b4a9cd":{"publicId":"0c969c38-7969-4bd9-9c91-f3cdf9b4a9cd","title":"百度开源 280B 参数 ERNIE 5.5 Flash Base 基座模型","status":"active","sourceCount":5,"reportCount":8,"firstReportAt":"2026-11-04T16:00:00.000Z","latestAt":"2026-11-06T02:49:21.000Z","latest":"百度开源 280B 参数的 ERNIE 5.5 Flash Base 基础模型","digest":"百度文心发布并开源基座模型 ERNIE-5.5-Flash-Base，开放预训练终点的权重，在 Hugging Face 提供 FP8 与 BF16 两种 safetensors 下载，采用 ERNIE 5.5 Flash Base Model License Agreement v1.0。百度称该模型为稀疏 MoE 基座语言模型，总参数 280B、每 token 激活 14B，预训练使用 33.5T tokens；权重未经中训练与后训练，供开发者做领域适配、指令微调和强化学习研究，后续将推出后训练版本。\n\n上下文长度上，百度称训练上下文达 128K，微调和推理设计上支持最长 1M-token。MarkTechPost 称其许可在年收入低于 5000 万美元时免费，但排除欧盟、英国和韩国。百度称该模型在同规模基座模型的多个基准上取得 SOTA，报道未给出独立验证。","digestUpdatedAt":"2026-11-06T04:15:31.054Z","reports":[{"id":"yspksmmwaaupllhpgbxcv124h","title":"百度开源 280B 参数的 ERNIE 5.5 Flash Base 基础模型","summary":"百度发布开源基础模型 ERNIE 5.5 Flash Base，参数规模为 280B。该推文附上 the-decoder.com 的报道链接，未给出更多技术细节。","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-06T02:49:21.000Z","url":"https://x.com/Baidu_Inc/status/2118536183663956194"},{"id":"uug280uzx0av4eec817jo9zru","title":"百度发布 ERNIE 5.5 Flash Base：280B 总参、14B 激活的 MoE 基座模型","summary":"百度发布 ERNIE 5.5 Flash Base，这是 280B 总参数、每 token 激活 14B 的稀疏 MoE 基座模型，权重止于预训练阶段，已在 Hugging Face 和 ModelScope 提供 FP8 与 BF16 权重。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-05T21:33:00.000Z","url":"https://www.marktechpost.com/2026/11/05/baidu-ernie-5-5-flash-base-280b-moe/"},{"id":"u0qd4l08l8jg213obn60phr42","title":"百度开源 ERNIE 5.5 Flash Base 基座模型，280B 参数 MoE 架构","summary":"百度发布开源基座模型 ERNIE-5.5-Flash-Base，刻意不带微调或后训练，交由开发者自行处理，后续将推出后训练版本。模型采用 MoE 架构，总参数 280B、每输入激活 14B，预训练数据 33.5 万亿 token，训练上下文最长 128,000 token，微调和推理设计上支持到 100 万 token。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-05T17:56:41.000Z","url":"https://the-decoder.com/baidu-releases-ernie-5-5-flash-base-with-280-billion-parameters-as-an-open-source-foundation-model/"},{"id":"r33a25ocq841v6voh3ypee22r","title":"百度发布 ERNIE 5.5 Flash Base 并上架 Hugging Face","summary":"百度发布 ERNIE 5.5 Flash Base 模型，提供官方博客介绍页 https://ernie.baidu.com/release/ernie-5-5-flash-base/ 和 Hugging Face 下载入口 https://huggingface.co/baidu/ERNIE-5.5-Flash-Base。","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-05T08:55:26.000Z","url":"https://x.com/Baidu_Inc/status/2118265926290419742"},{"id":"p6g76vm44wq8k5yw8oggf1sys","title":"百度开源 ERNIE 5.5 Flash Base 基座模型：280B 总参数、14B 激活","summary":"百度发布 ERNIE 5.5 Flash Base 稀疏 MoE 基座语言模型并开放权重。模型总参数 280B、每 token 激活 14B，预训练 33.5T tokens，微调和推理上下文最长 1M-token，提供 FP8 与 BF16 权重。官方称其在同规模基座模型中于多个基准取得 SOTA，权重直接来自预训练、未做中后期训练，方便研究者在同一 checkpoint 上比较不同方法的效果。","sourceName":"X：百度 Baidu (@Baidu_Inc)","firstParty":false,"publishedAt":"2026-11-05T08:55:25.000Z","url":"https://x.com/Baidu_Inc/status/2118265920665587935"},{"id":"bq5cyj48c8sy4kyvty60vigch","title":"百度文心开源 ERNIE-5.5-Flash-Base 基座模型，总参数 280B 每 token 激活 14B","summary":"百度文心发布开源基座模型 ERNIE-5.5-Flash-Base，开放 ERNIE 5.5 Flash 预训练终点权重。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-05T08:21:01.923Z","url":"https://www.ithome.com/1/022/785.htm"},{"id":"gxgg5gpnpv858z8ab6bqf0ijz","title":"百度开源 ERNIE-5.5-Flash-Base 基座模型","summary":"百度发布 ERNIE-5.5-Flash-Base 基座模型权重，为 280B 总参数、每 token 激活 14B 的稀疏 MoE 模型，从头在 33.5T tokens 上预训练，训练上下文达 128K，微调和推理支持 1M-token 上下文。","sourceName":"百度文心 ERNIE 官方博客","firstParty":true,"publishedAt":"2026-11-04T16:00:00.000Z","url":"https://ernie.baidu.com/release/ernie-5-5-flash-base/"},{"id":"r3360gkpmqpyyt2ii9cp1k9rz","title":"百度发布 ERNIE-5.5-Flash-Base 开源 Base 模型，280B 总参数每 token 激活 14B","summary":"百度文心团队发布 ERNIE-5.5-Flash-Base，在 Hugging Face 开放预训练终点 Base 权重，提供 FP8 与 BF16 两种 safetensors。","sourceName":"百度文心 ERNIE 官方博客","firstParty":true,"publishedAt":"2026-11-04T16:00:00.000Z","url":"https://ernie.baidu.com/zh/release/ernie-5-5-flash-base/"}]},"53c3f1bf-cba4-48c4-a7a3-2af0fcb95380":{"publicId":"53c3f1bf-cba4-48c4-a7a3-2af0fcb95380","title":"Meta 在美区 Muse 应用上线实时语音与表情头像","status":"active","sourceCount":9,"reportCount":9,"firstReportAt":"2026-11-05T18:30:24.000Z","latestAt":"2026-11-06T18:43:12.000Z","latest":"Muse 推出语音对话功能","digest":"Meta 在 Muse 应用中推出实时语音对话和会动的表情头像，先在美国上线，覆盖移动端、网页端和 Mac 应用。用户点击右上角电话图标即可开始对话，可以边说边让 Muse 帮忙完善想法，或排练面试、演讲；头像会随语气做出表情和手势，用户可选择仅语音、伴随头像或全屏显示，并有数百种声音可选。\n\nMeta 称，语音对话和表情头像目前仅在美国推出，之后将登陆 AI 眼镜和即将发货的 Muse Charm 设备。TechCrunch 报道称，该功能已向美国所有用户开放，支持通话和视频聊天；头像被昵称为 Jolly，可自定义为人、动物或其他角色。\n\nMeta 工程副总裁 David Singleton 称，Muse Realtime Voice 与 Muse Realtime Avatar 让语音、表情和手势保持同步，并能即时响应，用户可在它说话时随时插话。The Verge 称已在 iOS 应用上试用该功能。","digestUpdatedAt":"2026-11-06T18:45:38.239Z","reports":[{"id":"klcmxxgh0brp85kk54wbauytc","title":"Muse 推出语音对话功能","summary":"希望你们喜欢！","sourceName":"X：Christine Awad（Meta，Muse 设计） (@christinesed)","firstParty":false,"publishedAt":"2026-11-06T18:43:12.000Z","url":"https://x.com/christinesed/status/2118776229583376487"},{"id":"hrgtd1nycr9l6nynuqrdgg8wy","title":"Meta 个人 AI 助手 Muse 上线实时语音对话与虚拟形象功能","summary":"Meta CEO 扎克伯格 11 月 6 日在 Threads 宣布个人 AI 助手 Muse 正式上线实时语音对话与富有表现力的虚拟形象功能，率先面向美国用户，覆盖移动端、网页端和 Mac 应用。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-06T01:35:06.637Z","url":"https://www.ithome.com/1/023/069.htm"},{"id":"t5f9sggu46rbrai43e7e7msfi","title":"Meta 向美国用户开放 Muse AI 智能体实时视频通话","summary":"Meta 向全部美国用户开放与 Muse AI 智能体的实时视频通话，用户可与可换装的动画头像对话。技术上 Muse Realtime Voice 输出携带语音与表达信息的 speech tokens，Muse Realtime Avatar 将同一流转为口型同步视频，Meta 用知识蒸馏让学生模型以每视频块 2 次前向复现教师模型 120 次的效果。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-05T20:48:25.000Z","url":"https://x.com/rohanpaul_ai/status/2118445350621171974"},{"id":"kzw0ko779awmegtymuu4dxau7","title":"Meta 向美国全量用户开放 Muse AI 数字形象的语音与视频通话","summary":"Meta 宣布 Muse Voice 功能向美国所有用户开放，用户可与消费级 AI 智能体 Muse 通话和视频聊天。该功能由 Muse Realtime Avatar 和 Muse Realtime Voice 模型驱动，形象被昵称为 Jolly，可自定义为人、动物或其他角色，说话时配合匹配对话语气的表情和手势。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-05T19:48:28.000Z","url":"https://techcrunch.com/2026/11/05/meta-says-us-users-can-now-video-chat-with-their-muse-ai-avatar/"},{"id":"l0drmpkztayfzfqosdvfuu1pz","title":"Meta 推出 Muse 实时语音与虚拟形象","summary":"我们打造了 Muse Realtime Voice 和 Muse Realtime Avatar，让语音、表情和手势保持同步。它能即时响应，你还可以在它说话时随时插话。\n\n为打造这一功能的团队感到骄傲！","sourceName":"X：David Singleton（Meta MSL 工程副总裁，Muse） (@dps)","firstParty":false,"publishedAt":"2026-11-05T19:42:27.000Z","url":"https://x.com/dps/status/2118428749553393788"},{"id":"a6s8d1ajox1nvp3zmw1gsubqn","title":"Meta 的 Muse AI 智能体上线语音模式和会动的表现化身","summary":"Meta CEO Mark Zuckerberg 宣布 Muse AI 智能体现在支持实时语音对话，The Verge 作者已在 iOS 应用上试用。聊天时顶部的化身会随说话内容做动画，用户可让智能体自行决定语音语气或在化身设置中挑选。语音模式和表现化身现已在美区应用推出，随后将登陆 Meta 的 AI 眼镜和即将发货的 Muse Charm 设备。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-05T19:03:04.000Z","url":"https://www.theverge.com/tech/1028015/meta-muse-ai-voice-mode-expressive-avatar"},{"id":"mqzgcsqe43koz3olnucd1ts54","title":"Meta Muse 推出语音对话功能","summary":"推出语音功能。与你的 Muse 对话，Muse 会回应你，让你从“该做什么菜？”到直接下厨，就这么简单 ✨","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-05T18:35:44.000Z","url":"https://x.com/Muse/status/2118411960337289583"},{"id":"pmd4ouy6vz2ly0p14tkhszbqc","title":"Meta Muse 应用上线实时语音对话与表现力头像","summary":"Meta 在 Muse 应用的移动、网页和 Mac 端推出此前于 Connect 2026 预览的实时语音对话功能，点击右上角电话图标即可开始。语音模式下可以边说边让 Muse 帮忙完善想法或排练面试、演讲；头像会配合语气做出表情和手势，用户可选仅语音、伴随头像或全屏显示，并有数百种声音可选。","sourceName":"Meta：Newsroom · AI（RSS）","firstParty":true,"publishedAt":"2026-11-05T18:30:58.000Z","url":"https://about.fb.com/news/2026/11/introducing-muse-ai-voice-expressive-avatars/"},{"id":"fpvhi5z44xnzse9tt53oujo6y","title":"Meta Muse 应用上线实时语音对话","summary":"现在在 Muse 应用里：可以与你的 Muse 实时对话。还能从多种声音中选择 🗣️","sourceName":"X：Mark Zuckerberg (@finkd)","firstParty":false,"publishedAt":"2026-11-05T18:30:24.000Z","url":"https://x.com/finkd/status/2118410617698517088"}]},"5bb5d3ee-b9ff-4cb4-8df8-d487d6bc5b78":{"publicId":"5bb5d3ee-b9ff-4cb4-8df8-d487d6bc5b78","title":"Meta在Muse推出spaces并升级模型","status":"active","sourceCount":11,"reportCount":20,"firstReportAt":"2026-11-06T07:00:00.000Z","latestAt":"2026-11-06T22:37:46.000Z","latest":"Muse 最佳功能之一：Spaces 上线","digest":"Meta在Muse应用中推出spaces：用户描述规划器、追踪器、游戏等需求，Muse会直接在应用内生成可交互的类应用体验，用户可决定它放在哪个标签页、何时显示。Meta称spaces自发布起在Muse所有可用地区开放，连接相关应用后会在后台更新价格、日期等信息；分享空间以支持协作仍在探索中。\n\n同日，扎克伯格称Meta为Muse和Meta AI升级模型，把Muse Wonder中的Active Memory和Active Focus开放给所有用户。Meta称，新专用模型在Muse中遗忘关键信息的概率降低2.4倍，约束变化时摆脱卡壳的改善为67%；在Meta AI中则能更好地拆解复杂问题、提出更精准的追问并适应用户改变方向。这些效果数据来自Meta方面的说法。\n\nMeta研究博客另称，该专用模型使Personal Superintelligence Index得分从38%提升到47%。","digestUpdatedAt":"2026-11-06T22:52:48.458Z","reports":[{"id":"e1hkomdfzs7pogzav4cwc77wr","title":"Muse 最佳功能之一：Spaces 上线","summary":"Muse 最棒的功能之一！\n\nSpaces 来了。描述一个规划器、追踪器、游戏，或任何你需要的东西，Muse 会直接把它构建到应用里。把它固定到标签页，随时回来，它都已经是最新的。","sourceName":"X：Christine Awad（Meta，Muse 设计） (@christinesed)","firstParty":false,"publishedAt":"2026-11-06T22:37:46.000Z","url":"https://x.com/christinesed/status/2118835259236294992"},{"id":"n39uxtnh6dug6ex0vh8wiqmaz","title":"Meta 在 Muse 应用中推出 spaces","summary":"今天我们推出 spaces，这是一种在 Muse 应用内设计自定义体验的方式——从追踪孩子活动和作业的学校仪表盘，到汇集截止日期和发票的自由职业者中心。\n\nhttps://about.fb.com/news/2026/11/introducing-spaces-customize-muse-app/","sourceName":"X：Meta Newsroom (@MetaNewsroom)","firstParty":false,"publishedAt":"2026-11-06T21:21:27.000Z","url":"https://x.com/MetaNewsroom/status/2118816054281699651"},{"id":"cgwhg7w4jtgr1y99t89bci5t3","title":"Muse 用一句话搭建应用空间","summary":"创建一个空间非常简单。描述你想要的内容，Muse 就会把它构建到应用里，你还可以随时继续提出修改。","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T20:11:08.000Z","url":"https://x.com/Muse/status/2118798358261424598"},{"id":"v5vjx4aobiuh1oq96u26e5t4m","title":"Muse 推出 Spaces 自定义功能","summary":"为任何事物建一个空间，把它放进你的标签栏……这次更新后，你可以围绕自己关心的内容彻底重塑这款应用。\n\n你可以自定义每个新空间，也能自定义应用本身的结构。🎨🛠️","sourceName":"X：Alex Cornell（Meta，Muse 产品设计负责人） (@alexcornell)","firstParty":false,"publishedAt":"2026-11-06T19:16:35.000Z","url":"https://x.com/alexcornell/status/2118784629193036098"},{"id":"brr44mygbv5ze0dprgyu0f5it","title":"Muse 上线 Spaces 自定义应用功能","summary":"Spaces 来了。描述一个规划器、追踪器、游戏，或任何你需要的东西，Muse 会直接把它构建到应用里。把它固定到你的标签页，随时回来，它都已经是最新的。","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T19:08:01.000Z","url":"https://x.com/Muse/status/2118782474486501510"},{"id":"f39jep1clmad925kdw8wrjteo","title":"Meta 推出 Spaces，用于与 Muse 智能体按项目协作","summary":"Meta 为其 Muse 智能体推出新功能 Spaces，用户可在侧边栏按主题建立独立对话空间，Muse 会围绕特定目标代为推进，如度假规划、礼物追踪或婚礼策划。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-06T18:44:20.000Z","url":"https://techcrunch.com/2026/11/06/meta-introduces-spaces-a-new-way-to-collaborate-with-your-muse-agent/"},{"id":"u1t08iv9a4xlqlxsehgsi9ixv","title":"Meta Muse 团队分享 spaces 功能成果","summary":"为团队在 spaces 上完成的工作感到无比自豪！","sourceName":"X：Christine Awad（Meta，Muse 设计） (@christinesed)","firstParty":false,"publishedAt":"2026-11-06T18:42:45.000Z","url":"https://x.com/christinesed/status/2118776115141771618"},{"id":"y63iuulmd6zqa0f6325sh95y9","title":"Muse 用 spaces 打造感恩节烹饪指挥中心","summary":"最近我迷上了（往好处说？）规划感恩节做什么菜。这是我目前每周都会回来处理几次的任务，所以 Muse 帮我建了一个 space 来规划它、做好准备，它已经准备好在大日子当天成为我的指挥中心。\n\n我们打造 spaces，是为了让你做的工具能成为 Muse 本身的一部分。描述你需要什么，然后把它变成你的主标签页之一。","sourceName":"X：David Singleton（Meta MSL 工程副总裁，Muse） (@dps)","firstParty":false,"publishedAt":"2026-11-06T18:18:08.000Z","url":"https://x.com/dps/status/2118769921933062601"},{"id":"ong9nniyluwyzsd864rc4vxkl","title":"Meta 将 Muse Wonder 专项模型接入 Muse 和 Meta AI","summary":"Meta 推出用 Muse Wonder 训练的专项模型，接入 Muse 和 Meta AI，包含 Active Memory 和 Active Focus 两项能力。在 Muse 中，关键信息遗忘减少 2.4x，约束变化时摆脱卡壳的改善为 67%；Meta AI 则能更好地拆解复杂问题、提出更精准的追问并适应用户改变方向。","sourceName":"X：AI at Meta (@AIatMeta)","firstParty":false,"publishedAt":"2026-11-06T18:14:23.000Z","url":"https://x.com/AIatMeta/status/2118768974779634084"},{"id":"m3i39avenmad9qywqoncw99lt","title":"Meta Muse AI 推出自定义 spaces 功能，可生成类应用体验","summary":"Meta 为 Muse AI 助手推出名为 spaces 的新功能，用户可通过描述生成购物中心、学校看板、音乐追踪、问答游戏等类应用体验并直接在应用内交互。将 space 连接相关应用后，Muse 会在后台更新价格、日期等信息；用户可勾选、加笔记和编辑，把它加入侧边栏、移入主标签页或按时间安排显示。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-06T18:10:10.000Z","url":"https://www.theverge.com/tech/1028871/meta-muse-ai-spaces"},{"id":"lk4nacxtthqzmhs18hpq2dhd3","title":"扎克伯格宣布 Muse 与 Meta AI 模型升级，推出 Active Memory 和 Active Focus","summary":"Mark Zuckerberg 宣布为 Muse 和 Meta AI 升级模型，将 Muse Wonder 中的 Active Memory 和 Active Focus 带给所有用户。官方称新专用模型遗忘关键信息的概率降低 2.4 倍，自我纠错和完成日常任务的能力提升 67%，减少重复输入和卡死情况，详情见 research.meta.ai 博客。","sourceName":"X：Mark Zuckerberg (@finkd)","firstParty":false,"publishedAt":"2026-11-06T18:08:36.000Z","url":"https://x.com/finkd/status/2118767522782626104"},{"id":"ikff402u44w98djuk0e2gl67l","title":"Muse 展示 Instagram 收藏餐厅空间","summary":"今晚的空间特别推荐：你在 Instagram 上收藏却从未去过的每一家餐厅，附带价格、评分等更多信息 🍽️\n\n这些只是帮你入门的几个想法，但还有充足的空间（space）容纳更多。你会构建什么？","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:32.000Z","url":"https://x.com/Muse/status/2118767000260337895"},{"id":"oy5a39pb7ldthggq5jdrd85m5","title":"Muse 用 spaces 管理日常待办","summary":"事情太多太乱时，spaces 能帮忙处理生活中反复出现的待办事项。跟踪它们、查看到期时间，还能让 Muse 来帮忙 💈","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:31.000Z","url":"https://x.com/Muse/status/2118766995478827075"},{"id":"r7dbn1rjxah7ycf9ullzxwcp2","title":"Muse 节日购物按人整理","summary":"节日购物，按人整理：这个空间会记录尺码、预算，以及你从七月以来的每一个想法 🎁","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:30.000Z","url":"https://x.com/Muse/status/2118766993474216373"},{"id":"t510nwfzwnkr0s3dkie1kz2x3","title":"Muse 帮你盯紧所有上架信息","summary":"就差一枚硬币就能凑齐整套？这个空间帮你盯着所有上架信息 🪙","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:29.000Z","url":"https://x.com/Muse/status/2118766989279703429"},{"id":"uuyre0mg36145ktp60f7dknet","title":"Meta 空间内打造 Jolly Jump 游戏","summary":"无需游戏引擎，照样没问题。Jolly Jump 完全是在一个空间里构建出来的，你的创意也可以 👾","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:29.000Z","url":"https://x.com/Muse/status/2118766987576750427"},{"id":"af5ius9by5pguaqq44h9mrn28","title":"Meta 展示 Muse 应用自定义空间设计","summary":"设计专属于你的 Muse 应用。\n\n为任何你想要的内容构建空间，挑选标签页里放什么，甚至设定它们何时出现。\n\n以下是我们目前做的一些示例 ↓","sourceName":"X：Muse（Meta 个人智能体官方号） (@Muse)","firstParty":false,"publishedAt":"2026-11-06T18:06:28.000Z","url":"https://x.com/Muse/status/2118766983936197072"},{"id":"qu9pjazhrhr98lui6mvgz333w","title":"Meta Muse 空间功能体验","summary":"最近在玩 Muse 里的空间功能——告诉 Muse 你需要什么，它就能帮你搭建出来。\n\n我做了一个烧烤游戏、一个活动追踪器，还有一个家居控制面板。\n\n很期待看到大家能做出什么。","sourceName":"X：Mark Zuckerberg (@finkd)","firstParty":false,"publishedAt":"2026-11-06T18:01:39.000Z","url":"https://x.com/finkd/status/2118765774034579808"},{"id":"f3hogz1c4bmgbcwblqblumxpv","title":"Meta 在 Muse 应用中推出 spaces 自定义个性化体验","summary":"Meta 推出 spaces，一种在 Muse 内通过描述想法构建个性化体验的交互方式，例如节日礼物追踪、每日文字游戏或 DIY 规划板。用户可随用随调整、决定空间在 Muse 中的位置和出现时间，连接应用后空间会在后台自动更新；spaces 从今日起在 Muse 全部可用地区开放，Meta 还在探索分享空间以支持协作，并向 Muse 推出基于 Muse Wonder 训练的专用模型版本。","sourceName":"Meta：Newsroom · AI（RSS）","firstParty":true,"publishedAt":"2026-11-06T18:00:58.000Z","url":"https://about.fb.com/news/2026/11/introducing-spaces-customize-muse-app/"},{"id":"fjuidf0zii7na78sxru5il7pr","title":"Meta 将基于 Muse Wonder 训练的专用模型上线 Muse 与 Meta AI","summary":"Meta 宣布把基于 Muse Wonder 训练的专用模型推向 Muse 和 Meta AI 用户，Personal Superintelligence Index 得分从 38% 提升到 47%。","sourceName":"Meta AI：Research Blog（网页）","firstParty":true,"publishedAt":"2026-11-06T07:00:00.000Z","url":"https://research.meta.ai/blog/specialized-models-for-muse-and-metaai"}]}}};
